INSERT INTO monster VALUES (633,'Monstrous Scorpion','Monstrous Scorpion, Tiny',NULL,'Tiny','Vermin',NULL,'1/2 d8+2 (4 hp)','+0','20 ft. (4 squares)','14 (+2 size, +2 natural), touch 12, flat-footed 14','+0','-8','Claw +2 melee (1d2-4)','2 claws +2 melee (1d2-4) and sting -3 melee (1d2-4 plus poison)','2-1/2 ft.','0 ft.','Constrict 1d2-4, improved grab, poison','Darkvision 60 ft., tremorsense 60 ft., vermin traits','Fort +4, Ref +0, Will +0','Str 3, Dex 10, Con 14, Int -, Wis 10, Cha 2','Climb +0, Hide +12, Spot +4','Weapon Finesse',NULL,NULL,'Warm deserts','Colony (8-16)','1/4',NULL,'Always neutral','-','-','Constrict (Ex), Improved Grab (Ex), Poison (Ex)','Tiny monstrous scorpion; CR 1/4; Tiny vermin; HD 1/2 d8+2; hp 4; Init +0; Spd 20 ft. (4 squares); AC 14 (+2 size, +2 natural), touch 12, flat-footed 14; Base Atk +0; Grp -8; Atk +2 melee (1d2-4, claw); Full Atk +2 melee (1d2-4, 2 claws) and -3 melee (1d2-4 plus poison, sting); Space/Reach 2-1/2 ft./0 ft.; SA Constrict 1d2-4, improved grab, poison; SQ Darkvision 60 ft., tremorsense 60 ft., vermin traits; AL N; SV Fort +4, Ref +0, Will +0; Str 3, Dex 10, Con 14, Int -, Wis 10, Cha 2\n\nSkills and Feats: Climb +0, Hide +12, Spot +4; Weapon Finesse','\n      <div topic=\"Monstrous Scorpion\" level=\"2\"><p><h2>Monstrous Scorpion</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Monstrous Scorpion, Tiny</b><br/></td> \n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Tiny Vermin<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1/2 d8+2 (4 hp)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (+2 size, +2 natural), touch 12, flat-footed 14<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+0/-8<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Claw +2 melee (1d2-4)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 claws +2 melee (1d2-4) and sting -3 melee (1d2-4 plus poison)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>2-1/2 ft./0 ft.<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Constrict 1d2-4, improved grab, poison<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., tremorsense 60 ft., vermin traits<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +4, Ref +0, Will +0<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 3, Dex 10, Con 14, Int -, Wis 10, Cha 2<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +0, Hide +12, Spot +4<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Finesse <sup>B</sup><br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm deserts<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Colony (8-16)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/4<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n</table><p/><p/><p>Monstrous scorpions are likely to attack any creature that approaches, and they usually charge when attacking prey.</p><div topic=\"Constrict\" level=\"8\"><p><b>Constrict (Ex):</b> A monstrous scorpion deals automatic claw damage on a successful grapple check.</p>\n</div><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a monstrous scorpion must hit with a claw attack. A monstrous scorpion can use either its Strength modifier or Dexterity modifier for grapple checks, whichever is better.</p>\n</div><div topic=\"Poison\" level=\"8\"><p><b>Poison (Ex):</b> A monstrous scorpion has a poisonous sting. The details vary by the scorpion\'s size, as follows. The save DCs are Constitution- based. The indicated damage is initial and secondary damage.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td><b>Size</b><br/></td>\n<td><b>Fort DC</b><br/></td>\n<td><b>Damage</b><br/></td>\n<td><b>Size</b><br/></td>\n<td><b>Fort DC</b><br/></td>\n<td><b>Damage</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Tiny<br/></td>\n<td>12<br/></td>\n<td>1 Con<br/></td>\n<td>Huge<br/></td>\n<td>18<br/></td>\n<td>1d6 Con<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Small<br/></td>\n<td>12<br/></td>\n<td>1d2 Con<br/></td>\n<td>Gargantuan<br/></td>\n<td>23<br/></td>\n<td>1d8 Con<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Medium<br/></td>\n<td>13<br/></td>\n<td>1d3 Con<br/></td>\n<td>Colossal<br/></td>\n<td>33<br/></td>\n<td>1d10 Con<br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Large<br/></td>\n<td>14<br/></td>\n<td>1d4 Con<br/></td>\n<td/>\n<td/>\n<td/>\n\n</tr>\n</table>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A monstrous scorpion has a +4 racial bonus on Climb, Hide, and Spot checks.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersVermin');
