INSERT INTO monster VALUES (650,'Astral Construct','3rd-Level Astral Construct',NULL,'Medium','Construct',NULL,'3d10+20 (36 hp)','+2','40 ft. (8 squares)','20 (+2 Dex, +8 natural), touch 12, flat-footed 18','+4','+7','Slam +7 melee (1d6+7)','Slam +7 melee (1d6+7)','5 ft.','5 ft.','-','One ability from Menu A, construct traits, darkvision 60 ft., low-light vision','Fort +1, Ref +3, Will +1','Str 21, Dex 15, Con -, Int -, Wis 11, Cha 10','-',NULL,'-',NULL,'Any','Solitary','2','None','Always neutral','-','-','','3rd-level astral construct; CR 2; Medium construct; HD 3d10+20; hp 36; Init +2; Spd 40 ft. (8 squares); AC 20 (+2 dex, +8 natural), touch 12, flat-footed 18; Base Atk +4; Grp +7; Atk +7 melee (1d6+7, slam); Full Atk +7 melee (1d6+7, slam); Space/Reach 5 ft./5 ft.; SA -; SQ One ability from Menu A, construct traits, darkvision 60 ft., low-light vision; AL N; SV Fort +1, Ref +3, Will +1; Str 21, Dex 15, Con -, Int -, Wis 11, Cha 10\n\nSkills and Feats: -; -','\n      <div topic=\"3rd-Level Astral Construct\" level=\"5\"><p><h5>3RD-LEVEL ASTRAL CONSTRUCT</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>3rd-Level Astral Construct</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Construct<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>3d10+20 (36 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>20 (+2 Dex, +8 natural), touch 12, flat-footed 18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+4/+7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Slam +7 melee (1d6+7)<br/>