INSERT INTO monster VALUES (655,'Astral Construct','8th-Level Astral Construct',NULL,'Large','Construct',NULL,'16d10+30 (118 hp)','+1','40 ft. (8 squares)','29 (+1 Dex, +19 natural, -1 size), touch 10, flat-footed 28','+14','+30','Slam +25 melee (1d8+14)','2 slams +25 melee (1d8+14)','10 ft.','10 ft.','-','One ability from Menu C, construct traits, damage reduction 15/magic, darkvision 60 ft., low-light vision','Fort +5, Ref +6, Will +5','Str 39, Dex 13, Con -, Int -, Wis 11, Cha 10','-',NULL,'-',NULL,'Any','Solitary','9','None','Always neutral','-','-','','8th-level astral construct; CR 9; Large construct; HD 16d10+30; hp 118; Init +1; Spd 40 ft. (8 squares); AC 29 (+1 dex, +19 natural, -1 size), touch 10, flat-footed 28; Base Atk +14; Grp +30; Atk +25 melee (1d8+14, slam); Full Atk +25 melee (1d8+14, 2 slams); Space/Reach 10 ft./10 ft.; SA -; SQ One ability from Menu C, construct traits, damage reduction 15/magic, darkvision 60 ft., low-light vision; AL N; SV Fort +5, Ref +6, Will +5; Str 39, Dex 13, Con -, Int -, Wis 11, Cha 10\n\nSkills and Feats: -; -','\n      <div topic=\"8th-Level Astral Construct\" level=\"5\"><p><h5>8TH-LEVEL ASTRAL CONSTRUCT</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>8th-Level Astral Construct</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Construct<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>16d10+30 (118 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>29 (+1 Dex, +19 natural, -1 size), touch 10, flat-footed 28<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+14/+30<b