r maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Slam +28 melee (2d6+16)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 slams +28 melee (2d6+16)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./15 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Two abilities from Menu C, construct traits, damage reduction 15/magic, darkvision 60 ft., low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +6, Ref +6, Will +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 43, Dex 11, Con -, Int -, Wis 11, Cha 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p/>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (657,'Blue','Blue, 1st-Level Psion (Telepath)',NULL,'Small','Humanoid','Goblinoid, Psionic','1d4+1 plus 4 (10 hp)','+1','30 ft. (6 squares)','16 (+1 size, +1 Dex, +4 inertial armor), touch 12, flat-footed 15','+0','-6','Quarterstaff -2 melee (1d4-2) or light crossbow +1 ranged (1d6/19-20)','Quarterstaff -2 melee (1d4-2) or light crossbow +1 ranged (1d6/19-20)','5 ft.','5 ft.','Psionic powers','Darkvision 60 ft.','Fort +2, Ref +0, Will +3','Str 6, Dex 13, Con 14, Int 17, Wis 12, Cha 8','Concentration +6, Hide +7, Move Silently +5, Psicraft +7, Ride +5, Spot +3','Psionic Dodge','Psionic Body',NULL,'Temperate plains','Solitary, gang (1 plus 4-9 goblin warriors), band (2d10 plus 10-100 goblin warriors plus 100% noncombatants plus 1 3rd-level sergeant per 20 adults and 1 leader of 4th-6th level), warband (2d4 plus 10-24 goblin warriors with worg mounts), or tribe (4d10 plus 40-400 goblin warriors plus 100% noncombatants plus 1 3rd-level sergeant per 20 adults, 1 or 2 lieutenants of 4th or 5th level, 1 leader of 6th-8th level, 10-24 worgs, and 2-4 dire wolves)','1','Standard','Usually neutral evil','By character class (usually psion)','+1','','1st-level psion (telepath) blue; CR 1; Small humanoid (goblinoid, psionic); HD 1d4+1 plus 4; hp 10; Init +1; Spd 30 ft. (6 squares); AC 16 (+1 size, +1 dex, +4 inertial armor), touch 12, flat-footed 15; Base Atk +0; Grp -6; Atk -2 melee (1d4-2, quarterstaff) or +1 ranged (1d6/19-20, light crossbow); Full Atk -2 melee (1d4-2, quarterstaff) or +1 ranged (1d6/19-20, light crossbow); Space/Reach 5 ft./5 ft.; SA Psionic powers; SQ Darkvision 60 ft.; AL NE; SV Fort +2, Ref +0, Will +3; Str 6, Dex 13, Con 14, Int 17, Wis 12, Cha 8\n\nSkills and Feats: Concentration +6, Hide +7, Move Silently +5, Psicraft +7, Ride +5, Spot +3; Psionic Body, Psionic Dodge','\n      <div topic=\"Blue\" level=\"2\"><p><h2>Blue</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Blue, 1st-Level Psion (Telepath)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Humanoid (Goblinoid, Psionic)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d4+1 plus 4 (10 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (+1 size, +1 Dex, +4 inertial armor), touch 12, flat-footed 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+0/-6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Quarterstaff -2 melee (1d4-2) or light crossbow +1 ranged (1d6/19-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Quarterstaff -2 melee (1d4-2) or light crossbow +1 ranged (1d6/19-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Psionic powers<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +2, Ref +0, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 6, Dex 13, Con 14, Int 17, Wis 12, Cha 8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Concentration +6, Hide +7, Move Silently +5, Psicraft +7, Ride +5, Spot +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Psionic Body, Psionic Dodge <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate plains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, gang (1 plus 4-9 goblin warriors), band (2d10 plus 10-100 goblin warriors plus 100% noncombatants plus 1 3rd-level sergeant per 20 adults and 1 leader of 4th-6th level), warband (2d4 plus 10-24 goblin warriors with worg mounts), or tribe (4d10 plus 40-400 goblin warriors plus 100% noncombatants plus 1 3rd-level sergeant per 20 adults, 1 or 2 lieutenants of 4th or 5th level, 1 leader of 6th-8th level, 10-24 worgs, and 2-4 dire wolves)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class (usually psion)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n</table><p>Blues are a subrace of goblins with an innate knack for psionics. A blue is often smaller than an average goblin, standing just about 3 feet tall and weighing about 40 pounds. Blues have noticeably blue-tinged skin, and their eyes are less dull than those of a common goblin. Otherwise, they resemble their kin. They generally dress in short leather robes, dyed black.</p><p>Blues speak Goblin and Common.</p><p>Most blues encountered outside their homes are psions; the information in the statistics block is for a psion of 1st level.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Blues support goblin warriors in combat and are often called upon to lead a gang of goblins (from the rear) into battle.</p><div topic=\"Psionic Powers\" level=\"8\"><p><b>Psionic Powers:</b> The blue described here is a 1st-level psion.</p><p><i>Typical Psion Powers Known</i> (power points 3*; save DC 13 + power level): 1st-<i>inertial armor</i>,  <i>mind thrust</i> (DC 14), <i>psionic charm</i> (DC 14). Manifester level 1st. The save DCs are Intelligence-based.</p><p>Manifester level 1st. The save DCs are Intelligence-based.</p><p>*The blue shown here has already manifested <i>inertial armor</i>; its reserve is normally 4 power points.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Blues have a +4 racial bonus on Move Silently checks and Ride checks.</p><p>The blue psion presented here had the following ability scores before racial adjustments: Str 8, Dex 11, Con 12, Int 13, Wis 10, Cha 9.</p>\n</div>\n</div><div topic=\"Blues as Characters\" level=\"3\"><p><h3>Blues as Characters</h3></p><p>Blues tend to be psions, although blues raised in communities where their kind are rare may choose the path of the wilder.</p><p>Blue characters possess the following racial traits.</p><ul>\n <li>-2 Strength, +2 Intelligence, -2 Charisma.</li>\n <li>Small size: +1 bonus to Armor Class, +1 bonus on attack rolls, +4 bonus on Hide checks, -4 penalty on grapple checks, lifting and carrying limits 3/4 of those of Medium characters.</li>\n <li>Blue base land speed is 30 feet.</li>\n <li>Darkvision out to 60 feet.</li>\n <li>Naturally Psionic: Blues gain 1 bonus power point at 1st level.</li>\n <li>Racial Skills: A blue character has a +4 racial bonus on Move Silently checks and Ride checks.</li>\n <li>Automatic Languages: Common, Goblin. Bonus Languages: Draconic, Elven, Giant, Gnoll, Orc.</li>\n <li>Favored Class: Psion.</li>\n <li>Level Adjustment: +1.</li>\n</ul><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (658,'Brain Mole','Brain Mole',NULL,'Tiny','Magical Beast','Psionic','1d10-2 (3 hp)','+2','15 ft. (3 squares), burrow 15 ft.','14 (+2 size, +2 Dex), touch 14, flat-footed 12','+1','-11','Bite +5 melee (1d3-4)','Bite +5 melee (1d3-4)','2-1/2 ft.','0 ft.','Cascade flu, psi-like abilities','Low-light vision, power conversion, scent','Fort +0, Ref +4, Will +2','Str 2, Dex 14, Con 7, Int 2, Wis 14, Cha 11','Hide +15, Move Silently +7, Listen +6, Spot +2','Weapon Finesse','Alertness',NULL,'Temperate forest','Nest (3-8)','1/2','None','Always neutral','-','-','Cascade Flu (Ex), Hide Mind (Su), Power Conversion (Su)','Brain mole; CR 1/2; Tiny magical beast (psionic); HD 1d10-2; hp 3; Init +2; Spd 15 ft. (3 squares), burrow 15 ft.; AC 14 (+2 size, +2 dex), touch 14, flat-footed 12; Base Atk +1; Grp -11; Atk +5 melee (1d3-4, bite); Full Atk +5 melee (1d3-4, bite); Space/Reach 2-1/2 ft./0 ft.; SA Cascade flu, psi-like abilities; SQ Low-light vision, power conversion, scent; AL N; SV Fort +0, Ref +4, Will +2; Str 2, Dex 14, Con 7, Int 2, Wis 14, Cha 11\n\nSkills and Feats: Hide +15, Move Silently +7, Listen +6, Spot +2; Alertness, Weapon Finesse','\n      <div topic=\"Brain Mole\" level=\"2\"><p><h2>Brain Mole</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Brain Mole</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Tiny Magical Beast (Psionic)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d10-2 (3 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>15 ft. (3 squares), burrow 15 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (+2 size, +2 Dex), touch 14, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/-11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +5 melee (1d3-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +5 melee (1d3-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>2-1/2 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Cascade flu, psi-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision, power conversion, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +0, Ref +4, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 2, Dex 14, Con 7, Int 2, Wis 14, Cha 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +15, Move Silently +7, Listen +6, Spot +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Weapon Finesse <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate forest<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Nest (3-8)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Brain moles are burrowing animals that use psionic powers to overcome large psionic prey. Small, furry, and nearly blind, brain moles are almost indistinguishable from their common animal cousins.</p><p>Brain moles eat small insects when they can\'t get psionic energy.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Brain moles hunger for psionic energy. They hide in loose dirt and detritus on forest floors, watching for the approach of psionic creatures with their <i>detect psionics</i> power. When a suitable target comes in range, the brain moles then attack with their <i>power leech</i> ability. The moles remain hidden as long as possible. If threatened, they use <i>aversion</i> and <i>mind thrust</i> to discourage attackers, using their bite only as a last resort.</p><div topic=\"Cascade Flu\" level=\"8\"><p><b>Cascade Flu (Ex):</b> Disease-bite; Fortitude DC 9, incubation period one day, damage psionic cascade (every time an afflicted character manifests a power, she must make a DC 16 Concentration check; on a failed check, a psionic cascade is triggered [see Psionic Maladies]). The save DC is Constitution-based.</p>\n</div><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> At will-<i>detect psionics</i>,  <i>power leech</i> (ML 5th, DC 14); 3/day-<i>aversion</i> (DC 12),  <i>mind thrust</i> (DC 11). Manifester level 1st. The save DCs are Charisma-based.</p>\n</div><div topic=\"Hide Mind\" level=\"8\"><p><b>Hide Mind (Su):</b> A brain mole cannot be identified as psionic by divination spells or clairsentience powers.</p>\n</div><div topic=\"Power Conversion\" level=\"8\"><p><b>Power Conversion (Su):</b> When a brain mole drains a power point by means of its <i>power leech</i> power, it immediately heals 1 hit point. If it is already at full normal hit points, it instead gains psionic sustenance sufficient to supply its need for nourishment for 24 hours.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Brain moles have a +4 racial bonus on Hide and Move Silently checks and a -2 racial penalty on Spot checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (659,'Caller in Darkness','Caller in Darkness',NULL,'Large','Undead','Incorporeal, Psionic','11d12 (71 hp)','+7','30 ft. (6 squares), fly 60 ft. (good)','14 (-1 size, +3 Dex, +2 deflection), touch 14, flat-footed 11','+5','-','Incorporeal touch +7 melee (2d6)','4 incorporeal touches +7 melee (2d6)','10 ft.','10 ft.','Psi-like abilities, steal essence','Incorporeal traits, undead traits, unnatural aura, vulnerability to sunlight','Fort +3, Ref +6, Will +9','Str -, Dex 16, Con -, Int 14, Wis 14, Cha 15','Hide +9, Intimidate +12, Knowledge (psionics) +12, Listen +14, Psicraft +12, Search +12, Sense Motive +12, Spot +14',NULL,'Blind-Fight, Combat Reflexes, Improved Initiative, Weapon Finesse',NULL,'Underground','Solitary','9','None','Always chaotic evil','12-22 HD (Large); 23-33 HD (Huge)','-','Steal Essence (Su), Unnatural Aura (Su), Vulnerability to Sunlight (Ex)','Caller in darkness; CR 9; Large undead (incorporeal, psionic); HD 11d12; hp 71; Init +7; Spd 30 ft. (6 squares), fly 60 ft. (good); AC 14 (-1 size, +3 dex, +2 deflection), touch 14, flat-footed 11; Base Atk +5; Grp -; Atk +7 melee (2d6, incorporeal touch); Full Atk +7 melee (2d6, 4 incorporeal touches); Space/Reach 10 ft./10 ft.; SA Psi-like abilities, steal essence; SQ Incorporeal traits, undead traits, unnatural aura, vulnerability to sunlight; AL CE; SV Fort +3, Ref +6, Will +9; Str -, Dex 16, Con -, Int 14, Wis 14, Cha 15\n\nSkills and Feats: Hide +9, Intimidate +12, Knowledge (psionics) +12, Listen +14, Psicraft +12, Search +12, Sense Motive +12, Spot +14; Blind-Fight, Combat Reflexes, Improved Initiative, Weapon Finesse','\n      <div topic=\"Caller in Darkness\" level=\"2\"><p><h2>Caller in Darkness</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Caller in Darkness</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Undead (Incorporeal, Psionic)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>11d12 (71 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares), fly 60 ft. (good)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (-1 size, +3 Dex, +2 deflection), touch 14, flat-footed 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+5/-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Incorporeal touch +7 melee (2d6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>4 incorporeal touches +7 melee (2d6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Psi-like abilities, steal essence<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Incorporeal traits, undead traits, unnatural aura, vulnerability to sunlight<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +6, Will +9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str -, Dex 16, Con -, Int 14, Wis 14, Cha 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +9, Intimidate +12, Knowledge (psionics) +12, Listen +14, Psicraft +12, Search +12, Sense Motive +12, Spot +14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Blind-Fight, Combat Reflexes, Improved Initiative, Weapon Finesse<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always chaotic evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>12-22 HD (Large); 23-33 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A caller in darkness is an incorporeal creature composed of the minds of dozens of victims who died together in terror. It seeks to draw others into its fearwracked, hellish existence.</p><p>Callers in darkness rarely speak, but when they do, they speak Common.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> At will-<i>clairvoyant sense</i>,  <i>concussion blast</i> (two targets, 3d6*),  <i>detect psionics</i>,  <i>ego whip</i> (2d4, DC 16*), <i>mind thrust</i> (7d10, DC 16*); 3/day-<i>death urge</i> (DC 16), <i>psychic crush</i> (DC 13**), <i>psionic suggestion</i> (three targets, DC 14*); 1/day-<i>co-opt concentration</i> (DC 18). Manifester level 7th. The save DCs are Charisma-based.</p><p>*Includes augmentation for the caller\'s manifester level.</p><p>**Includes the inherent +4 save adjustment described in the power.</p>\n</div><div topic=\"Steal Essence\" level=\"8\"><p><b>Steal Essence (Su):</b> Any living, intelligent creature slain by a caller in darkness\'s touch attack is mentally absorbed into the monster\'s consciousness. (The physical body of the victim remains intact). Stealing a victim\'s essence is a free action; it grants the caller 12 temporary hit points, and a permanent new screaming face appears within its cloud.</p><p>A caller in darkness can also steal the essence of living, intelligent creatures within 30 feet that are paralyzed or sleeping, or that are helpless due to having a mental ability score reduced to 0 (often by the caller\'s <i>ego whip</i> attack). Doing so is a standard action that provokes attacks of opportunity. The victim dies, and the caller gains 12 temporary hit points.</p>\n</div><div topic=\"Incorporeal Traits\" level=\"8\"><p><b>Incorporeal Traits:</b> A caller in darkness is harmed only by other incorporeal creatures, magic weapons, spells, spell-like abilities, and supernatural abilities. It has a 50% chance to ignore any damage from a corporeal source, except for force effects or attacks made with ghost touch weapons. It can pass through solid objects, but not force effects, at will. Its attacks ignore natural armor, armor, and shields, but deflection bonuses and force effects work normally against them. The creature always moves silently and cannot be heard with Listen checks if it doesn\'t wish to be.</p>\n</div><div topic=\"Undead Traits\" level=\"8\"><p><b>Undead Traits:</b> A caller in darkness is immune to mind-affecting effects, poison, <i>sleep</i>,  paralysis, stunning, disease, death effects, and any effect that requires a Fortitude save unless it also works on objects or is harmless. It is not subject to critical hits, nonlethal damage, ability damage to its physical ability scores, ability drain, energy drain, fatigue, exhaustion, or death from massive damage. It cannot be raised, and <i>resurrection</i> works only if it is willing. It has darkvision out to 60 feet.</p>\n</div><div topic=\"Unnatural Aura\" level=\"8\"><p><b>Unnatural Aura (Su):</b> Animals can sense the unnatural presence of a caller in darkness. Any animal within 30 feet must make a DC 17 Will save or become panicked until it is no longer within 30 feet of the caller in darkness. A panicked creature that is cornered begins cowering. The save DC is Charisma-based.</p>\n</div><div topic=\"Vulnerability to Sunlight\" level=\"8\"><p><b>Vulnerability to Sunlight (Ex):</b> Callers in darkness are utterly powerless in natural sunlight (not merely a <i>daylight</i> spell) and flee from it. A caller caught in sunlight cannot attack and can take only a single move action or standard action each turn, but  not both (nor can it take full-round actions).</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (660,'Cerebrilith','Cerebrilith',NULL,'Large','Outsider','Chaotic, Evil, Extraplanar, Psionic','9d8+63 (103 hp)','+1','30 ft. (6 squares)','25 (-1 size, +1 Dex, +15 natural), touch 10, flat-footed 24','+9','+19','Bite +14 melee (1d8+6)','Bite +14 melee (1d8+6) and 2 claws +9 melee (1d6+3)','10 ft.','10 ft.','Psi-like abilities, spell-like abilities, summon demon','Damage reduction 10/good, darkvision 60 ft., immunity to electricity and poison, outsider traits, psionic traits, acid resistance 10, cold resistance 10, fire resistance 10, power resistance 20, telepathy 100 ft.','Fort +13, Ref +7, Will +10','Str 22, Dex 13, Con 25, Int 15, Wis 18, Cha 21','Concentration +17, Hide +7, Jump +16, Knowledge (arcana) +12, Knowledge (psionics) +12, Knowledge (the planes) +12, Listen +22, Move Silently +11, Psicraft +12, Search +12, Sense Motive +14, Spot +22','Wild Talent','Power Attack, Psionic Meditation, Psionic Fist, Unavoidable Strike',NULL,'Chaotic evil planes','Solitary or gang (2-4)','10','Standard','Always chaotic evil','10-18 HD (Large); 19-27 HD (Huge)','+9','Summon Demon (Sp)','Cerebrilith; CR 10; Large outsider (chaotic, evil, extraplanar, psionic); HD 9d8+63; hp 103; Init +1; Spd 30 ft. (6 squares); AC 25 (-1 size, +1 dex, +15 natural), touch 10, flat-footed 24; Base Atk +9; Grp +19; Atk +14 melee (1d8+6, bite); Full Atk +14 melee (1d8+6, bite) and +9 melee (1d6+3, 2 claws); Space/Reach 10 ft./10 ft.; SA Psi-like abilities, spell-like abilities, summon demon; SQ Damage reduction 10/good, darkvision 60 ft., immunity to electricity and poison, outsider traits, psionic traits, acid resistance 10, cold resistance 10, fire resistance 10, power resistance 20, telepathy 100 ft.; AL CE; SV Fort +13, Ref +7, Will +10; Str 22, Dex 13, Con 25, Int 15, Wis 18, Cha 21\n\nSkills and Feats: Concentration +17, Hide +7, Jump +16, Knowledge (arcana) +12, Knowledge (psionics) +12, Knowledge (the planes) +12, Listen +22, Move Silently +11, Psicraft +12, Search +12, Sense Motive +14, Spot +22; Power Attack, Psionic Fist, Psionic Meditation, Unavoidable Strike, Wild Talent','\n      <div topic=\"Cerebrilith\" level=\"2\"><p><h2>Cerebrilith</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Cerebrilith</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Outsider (Chaotic, Evil, Extraplanar, Psionic)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>9d8+63 (103 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>25 (-1 size, +1 Dex, +15 natural), touch 10, flat-footed 24<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+9/+19<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +14 melee (1d8+6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +14 melee (1d8+6) and 2 claws +9 melee (1d6+3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Psi-like abilities, spell-like abilities, <i>summon demon</i><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Damage reduction 10/good, darkvision 60 ft., immunity to electricity and poison, outsider traits, psionic traits, acid resistance 10, cold resistance 10, fire resistance 10, power resistance 20, telepathy 100 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +13, Ref +7, Will +10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 22, Dex 13, Con 25, Int 15, Wis 18, Cha 21<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Concentration +17, Hide +7, Jump +16, Knowledge (arcana) +12, Knowledge (psionics) +12, Knowledge (the planes) +12, Listen +22, Move Silently +11, Psicraft +12, Search +12, Sense Motive +14, Spot +22<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Power Attack, Psionic Meditation, Psionic Fist, Unavoidable Strike, Wild Talent <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Chaotic evil planes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or gang (2-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always chaotic evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>10-18 HD (Large); 19-27 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+9<br/></td>\n\n</tr>\n</table><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Cerebriliths favor telepathic attacks, usually beginning a battle by launching a furious barrage of <i>ego whip</i> and <i>id insinuation</i> attacks. In melee, cerebriliths often use their Concentration skill to gain psionic focus, so that they can use Psionic Fist or Unavoidable Strike (the latter in conjunction with Power Attack).</p><p>A cerebrilith\'s natural weapons, as well as any weapons it wields, are treated as chaotic-aligned and evil-aligned for the purpose of overcoming damage reduction.</p><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> At will-<i>brain lock</i> (any nonmindless, DC 17*), <i>detect psionics</i>,  <i>ego whip</i> (2d4, DC 19*),  <i>id insinuation</i> (four targets, DC 20*),  <i>mind trap</i> (5 rounds*); 3/day-<i>psionic dominate</i> (24 hours, DC 20*), <i>ectoplasmic form</i>, <i>mind probe</i> (DC 20); 1/day-<i>mind thrust</i> (9d10, DC 20*). Manifester level 9th. The save DCs are Charisma-based.</p><p>*Includes augmentation for the cerebrilith\'s manifester level.</p>\n</div><div topic=\"Spell-Like Abilities\" level=\"8\"><p><b>Spell-Like Abilities:</b> At will-<i>deeper darkness</i>,  <i>desecrate</i>,  <i>detect good</i>,  <i>dispel good</i> (DC 20),  <i>greater teleport</i> (self plus 50 pounds of objects only), <i>magic circle against good</i> (DC 18),  <i>unholy blight</i> (DC 19). Caster level 9th. The save DCs are Charisma-based.</p>\n</div><div topic=\"Summon Demon\" level=\"8\"><p><b>Summon Demon (Sp):</b> Once per day a cerebrilith can attempt to summon 4d6 dretches or another cerebrilith with a 35% chance of success. This ability is equivalent to a 4th-level spell.</p>\n</div><div topic=\"Outsider Traits\" level=\"8\"><p><b>Outsider Traits:</b> A cerebrilith cannot be <i>raised</i>,  <i>reincarnated</i> or <i>resurrected</i> (though a <i>limited wish</i>,  <i>wish</i>, <i>miracle</i>, or <i>true resurrection</i> spell can restore life). It has darkvision out to 60 feet.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Cerebriliths have a +8 racial bonus on Listen and Spot checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (661,'Couatl, Psionic','Couatl, Psionic',NULL,'Large','Outsider','Native, Psionic','9d8+18 (58 hp)','+7','20 ft. (4 squares), fly 60 ft. (good)','21 (-1 size, +3 Dex, +9 natural), touch 12, flat-footed 18','+9','+17','Bite +12 melee (1d3+6 plus poison)','Bite +12 melee (1d3+6 plus poison)','10 ft.','5 ft.','Constrict 2d8+6, improved grab, poison, psi-like abilities, spells','Darkvision 60 ft., ethereal jaunt, telepathy 90 ft.','Fort +8, Ref +9, Will +10','Str 18, Dex 16, Con 14, Int 17, Wis 19, Cha 17','Concentration +14, Diplomacy +17, Jump +0, Knowledge (any two) +15, Listen +16, Search +15, Sense Motive +16, Spellcraft +15 (+17 scrolls), Spot +16, Survival +4 (+6 following tracks), Tumble +15, Use Magic Device +15 (+17 scrolls)','Eschew Materials','Dodge, Empower Spell, Hover, Improved Initiative',NULL,'Warm forests','Solitary, pair, or flight (3-6)','10','Standard','Always lawful good','10-13 HD (Large); 14-27 HD (Huge)','+7','Constrict (Ex), Ethereal Jaunt (Su), Improved Grab (Ex), Poison (Ex), Telepathy (Su)','Psionic couatl; CR 10; Large outsider (native, psionic); HD 9d8+18; hp 58; Init +7; Spd 20 ft. (4 squares), fly 60 ft. (good); AC 21 (-1 size, +3 dex, +9 natural), touch 12, flat-footed 18; Base Atk +9; Grp +17; Atk +12 melee (1d3+6 plus poison, bite); Full Atk +12 melee (1d3+6 plus poison, bite); Space/Reach 10 ft./5 ft.; SA Constrict 2d8+6, improved grab, poison, psi-like abilities, spells; SQ Darkvision 60 ft., ethereal jaunt, telepathy 90 ft.; AL LG; SV Fort +8, Ref +9, Will +10; Str 18, Dex 16, Con 14, Int 17, Wis 19, Cha 17\n\nSkills and Feats: Concentration +14, Diplomacy +17, Jump +0, Knowledge (any two) +15, Listen +16, Search +15, Sense Motive +16, Spellcraft +15 (+17 scrolls), Spot +16, Survival +4 (+6 following tracks), Tumble +15, Use Magic Device +15 (+17 scrolls); Dodge, Empower Spell, Eschew Materials, Hover, Improved Initiative','\n      <div topic=\"Couatl, Psionic\" level=\"2\"><p><h2>Couatl, Psionic</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Couatl, Psionic</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Outsider (Native, Psionic)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>9d8+18 (58 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), fly 60 ft. (good)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>21 (-1 size, +3 Dex, +9 natural), touch 12, flat-footed 18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+9/+17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +12 melee (1d3+6 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +12 melee (1d3+6 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Constrict 2d8+6, improved grab, poison, psi-like abilities, spells<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., ethereal jaunt, telepathy 90 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +8, Ref +9, Will +10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 18, Dex 16, Con 14, Int 17, Wis 19, Cha 17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Concentration +14, Diplomacy +17, Jump +0, Knowledge (any two) +15, Listen +16, Search +15, Sense Motive +16, Spellcraft +15 (+17 scrolls), Spot +16, Survival +4 (+6 following tracks), Tumble +15, Use Magic Device +15 (+17 scrolls)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Dodge, Empower Spell, Eschew Materials <sup>B</sup>, Hover, Improved Initiative<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm forests<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, or flight (3-6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always lawful good<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>10-13 HD (Large); 14-27 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+7<br/></td>\n\n</tr>\n</table><p>A couatl is about 12 feet long, with a wingspan of about 15 feet. It weighs about 1,800 pounds.</p><p>Couatls speak Celestial, Common, and Draconic, and also have the power of telepathy (see below).</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A couatl uses its <i>detect thoughts</i> ability on any creature that arouses its suspicions. Since it is highly intelligent, a couatl usually casts spells from a distance before closing. If more than one couatl is involved, they discuss their strategy before a battle.</p><p>The psionic couatl does not possess the psionic spell-like abilities of the standard couatl. Instead, it has psi-like abilities.</p><div topic=\"Constrict\" level=\"8\"><p><b>Constrict (Ex):</b> A couatl deals 2d8+6 points of damage with a successful grapple check.</p>\n</div><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a couatl must hit a creature of up to two size categories larger with its bite attack. It can then attempt to start a grapple as a free action without provoking an attack of opportunity. If it wins the grapple check, it establishes a hold and can constrict.</p>\n</div><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> At will-<i>aura sight</i>, <i>cloud mind</i> (DC 15), <i>detect psionics</i>, <i>read thoughts</i> (DC 15); 3/day-<i>mental barrier</i> (2 rounds*), <i>metamorphosis</i>, <i>psionic plane shift</i>, <i>thought shield</i> (power resistance 19*). Manifester level 9th. The save DCs are Charisma-based.</p><p>*Includes augmentation for the psionic couatl\'s manifester level.</p>\n</div><div topic=\"Poison\" level=\"8\"><p><b>Poison (Ex)</b>: Injury, Fortitude DC 16, initial damage 2d4 Str, secondary damage 4d4 Str.</p><p>The save DC is Constitution-based.</p>\n</div><div topic=\"Spells\" level=\"8\"><p><b>Spells:</b> A couatl casts spells as a 9th-level sorcerer.</p><p>It can choose its spells known from the sorcerer list, the cleric list, and from the lists for the Air, Good, and Law domains. The cleric spells and domain spells are considered arcane spells for a couatl, meaning that the creature does not need a divine focus to cast them.</p><p><i>Typical Spells Known</i> (6/7/7/7/4; save DC 13 + spell level): 0-<i>cure minor wounds</i>,  <i>daze</i>,  <i>disrupt undead</i>,  <i>light</i>,  <i>obscuring mist</i>,  <i>ray of frost</i>,  <i>read magic</i>,  <i>resistance</i>; 1st-<i>endure elements</i>,  <i>mage armor</i>,  <i>protection from chaos</i>,  <i>true strike</i>,  <i>wind wall</i>; 2nd-<i>cure moderate wounds</i>,  <i>eagle\'s splendor</i>,  <i>scorching ray</i>,  <i>silence</i>; 3rd-<i>gaseous form</i>,  <i>magic circle against evil</i>,  <i>summon monster III</i>; 4th- <i>charm monster</i>,  <i>freedom of movement</i>.</p>\n</div><div topic=\"Ethereal Jaunt\" level=\"8\"><p><b>Ethereal Jaunt (Su):</b> This ability works like the <i>ethereal jaunt</i> spell (caster level 16th).</p>\n</div><div topic=\"Telepathy\" level=\"8\"><p><b>Telepathy (Su):</b> A couatl can communicate telepathically with any creature within 90 feet that has an Intelligence score. The creature can respond to the couatl if it wishes-no common language is needed.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (662,'Crysmal','Crysmal',NULL,'Small','Elemental','Earth, Psionic','6d8+6 (33 hp)','+2','30 ft. (6 squares), burrow 20 ft.','21 (+1 size, +2 Dex, +8 natural), touch 13, flat-footed 19','+4','+2','Sting +7 melee (1d3+3)','Sting +7 melee (1d3+3)','5 ft.','5 ft.','Psi-like abilities','Damage reduction 5/bludgeoning, elemental traits, immunity to fire and cold, electricity resistance 15','Fort +8, Ref +6, Will +2','Str 15, Dex 14, Con 12, Int 6, Wis 10, Cha 14','Appraise +9, Climb +5, Jump +5, Listen +2, Spot +10',NULL,'Alertness, Great Fortitude, Lightning Reflexes',NULL,'Underground','Solitary or facet (2-5)','3','Double goods (gems only)','Any lawful','7-12 HD (Medium); 13-18 HD (Large)','-','','Crysmal; CR 3; Small elemental (earth, psionic); HD 6d8+6; hp 33; Init +2; Spd 30 ft. (6 squares), burrow 20 ft.; AC 21 (+1 size, +2 dex, +8 natural), touch 13, flat-footed 19; Base Atk +4; Grp +2; Atk +7 melee (1d3+3, sting); Full Atk +7 melee (1d3+3, sting); Space/Reach 5 ft./5 ft.; SA Psi-like abilities; SQ Damage reduction 5/bludgeoning, elemental traits, immunity to fire and cold, electricity resistance 15; AL LN; SV Fort +8, Ref +6, Will +2; Str 15, Dex 14, Con 12, Int 6, Wis 10, Cha 14\n\nSkills and Feats: Appraise +9, Climb +5, Jump +5, Listen +2, Spot +10; Alertness, Great Fortitude, Lightning Reflexes','\n      <div topic=\"Crysmal\" level=\"2\"><p><h2>Crysmal</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Crysmal</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Elemental (Earth, Psionic)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>6d8+6 (33 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares), burrow 20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>21 (+1 size, +2 Dex, +8 natural), touch 13, flat-footed 19<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+4/+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Sting +7 melee (1d3+3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Sting +7 melee (1d3+3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Psi-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Damage reduction 5/bludgeoning, elemental traits, immunity to fire and cold, electricity resistance 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +8, Ref +6, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 15, Dex 14, Con 12, Int 6, Wis 10, Cha 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Appraise +9, Climb +5, Jump +5, Listen +2, Spot +10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Great Fortitude, Lightning Reflexes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or facet (2-5)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Double goods (gems only)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Any lawful<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>7-12 HD (Medium); 13-18 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A conglomerate of stone and crystal, a crysmal above all else seeks to perpetuate its kind.</p><p>Crysmals transform mundane minerals into juvenile crysmals. Gems are the perfect substance for this reproductive cycle: To make a single juvenile, a crysmal generally needs eight to ten gems, each of 25 gp value or more.</p><p>Crysmals understand Terran but do not speak.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> At will-<i>control object</i>,  <i>control sound</i>,  <i>detect psionics</i>,  <i>empty mind</i>,  <i>mind thrust</i> (2d10, DC 13*); 3/day-<i>psionic dimension door</i>. Manifester level 2nd. The save DCs are Charisma-based.</p><p>*Includes augmentation for the crysmal\'s manifester level.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Crysmals have a +8 racial bonus on Appraise checks and Spot checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (663,'Dromite','Dromite, 1st-Level Warrior',NULL,'Small','Monstrous Humanoid','Psionic','1d8+1 (5 hp)','+0','20 ft. (4 squares)','18 (+1 size, +3 natural armor, +3 studded leather, +1 light shield), touch 11, flat-footed 18','+1','-3','Longsword +3 melee (1d6/19-20) or light crossbow +2 ranged (1d6/19-20)','Longsword +3 melee (1d6/19-20) or light crossbow +2 ranged (1d6/19-20)','5 ft.','5 ft.','Psi-like abilities','Darkvision 60 ft., fire resistance 5, scent','Fort +3, Ref +0, Will -2','Str 11, Dex 11, Con 12, Int 10, Wis 7, Cha 10','Climb +2, Spot +4','Blind-Fight','Weapon Focus (longsword)',NULL,'Underground','Squad (2-4), company (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level), or band (30-100 plus 100% noncombatants plus 1 3rdlevel sergeant per 20 adults, 5 5th-level lieutenants, 3 7th-level captains, 6-10 giant beetles, and 2-5 riding giant beetles)','1/2','Standard','Usually neutral','By character class','+1','','1st-level warrior dromite; CR 1/2; Small monstrous humanoid (psionic); HD 1d8+1; hp 5; Init +0; Spd 20 ft. (4 squares); AC 18 (+1 size, +3 natural armor, +3 studded leather, +1 light shield), touch 11, flat-footed 18; Base Atk +1; Grp -3; Atk +3 melee (1d6/19-20, longsword) or +2 ranged (1d6/19-20, light crossbow); Full Atk +3 melee (1d6/19-20, longsword) or +2 ranged (1d6/19-20, light crossbow); Space/Reach 5 ft./5 ft.; SA Psi-like abilities; SQ Darkvision 60 ft., fire resistance 5, scent; AL N; SV Fort +3, Ref +0, Will -2; Str 11, Dex 11, Con 12, Int 10, Wis 7, Cha 10\n\nSkills and Feats: Climb +2, Spot +4; Blind-Fight, Weapon Focus (longsword)','\n      <div topic=\"Dromite\" level=\"2\"><p><h2>Dromite</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Dromite, 1st-Level Warrior<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Monstrous Humanoid (Psionic)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d8+1 (5 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>18 (+1 size, +3 natural armor, +3 studded leather, +1 light shield), touch 11, flat-footed 18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/-3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Longsword +3 melee (1d6/19-20) or light crossbow +2 ranged (1d6/19-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Longsword +3 melee (1d6/19-20) or light crossbow +2 ranged (1d6/19-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Psi-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., fire resistance 5, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +0, Will -2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 11, Dex 11, Con 12, Int 10, Wis 7, Cha 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +2, Spot +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Focus (longsword), Blind-Fight <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Squad (2-4), company (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level), or band (30-100 plus 100% noncombatants plus 1 3rdlevel sergeant per 20 adults, 5 5th-level lieutenants, 3 7th-level captains, 6-10 giant beetles, and 2-5 riding giant beetles)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n</table><p>Dromites stand about 3 feet tall and usually weigh slightly more than 30 pounds. They have iridescent compound eyes. Dromites wear heavy boots and light clothing, and are sometimes content with just a sturdy harness.</p><p>Dromites speak Common.</p><p>Most dromites encountered outside their homes are warriors; the information in the statistics block is for a warrior of 1st level.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> 1/day: <i>energy ray</i> (fire, 1d6+1). Manifester level 1st. The save DC is Charisma-based. (Other dromites may manifest electricity, cold, or sonic <i>energy rays</i> instead; the <i>energy ray</i> always matches the type of energy the dromite is resistant to.)</p><p>The dromite warrior presented here had the following ability scores before racial adjustments: Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8.</p>\n</div>\n</div><div topic=\"Dromites as Characters\" level=\"3\"><p><h3>Dromites as Characters</h3></p><p>Dromite characters possess the following racial traits.</p><ul>\n <li>+2 Charisma, -2 Strength, -2 Wisdom.</li>\n <li>Small size: +1 bonus to Armor Class, +1 bonus on attack rolls, +4 bonus on Hide checks, -4 penalty on grapple checks, lifting and carrying limits 3/4 of those of Medium characters.</li>\n <li>Dromite base land speed is 20 feet.</li>\n <li>+3 natural armor bonus.</li>\n <li>Naturally Psionic: Dromites gain 1 bonus power point at 1st level.</li>\n <li>Special Attacks (see above): Psi-like abilities.</li>\n <li>Special Qualities (see above): Resistance to fire 5 (other dromites may have resistance to cold, electricity, or sonics instead of fire), scent.</li>\n <li>Racial Skills: Dromites have a +2 racial bonus on Spot checks due to their compound eyes.</li>\n <li>Racial Feats: Dromites gain Blind-fight as a bonus feat.</li>\n <li>Automatic Languages: Common. Bonus Languages: Dwarven, Gnome, Goblin, Terran.</li>\n <li>Favored Class: Wilder.</li>\n <li>Level Adjustment: +1.</li>\n</ul><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (664,'Elan','Elan, 1st-Level Warrior',NULL,'Medium','Aberration','Psionic','1d8+1 (5 hp)','+0','30 ft. (6 squares)','14 (+3 studded leather, +1 light shield), touch 10, flat-footed 14','+1','+2','Warhammer +3 melee (1d8+1/x3) or longbow +1 ranged (1d8/x3)','Warhammer +3 melee (1d8+1/x3) or longbow +1 ranged (1d8/x3)','5 ft.','5 ft.','-','Repletion, resilience, resistance','Fort +3, Ref +0, Will -1','Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 6','Climb +3, Jump +3',NULL,'Weapon Focus (warhammer)',NULL,'Any','Congregate (2-4), squad (11-20 plus 2 3rdlevel sergeants and 1 leader of 3rd-6th level), or band (30-100 plus 150% noncombatants plus 1 3rd-level sergeant per 10 adults, 5 5thlevel lieutenants, and 3 7thlevel captains)','1/2','Standard','Usually neutral','By character class','+0','Repletion (Su), Resilience (Su), Resistance (Su)','1st-level warrior elan; CR 1/2; Medium aberration (psionic); HD 1d8+1; hp 5; Init +0; Spd 30 ft. (6 squares); AC 14 (+3 studded leather, +1 light shield), touch 10, flat-footed 14; Base Atk +1; Grp +2; Atk +3 melee (1d8+1/x3, warhammer) or +1 ranged (1d8/x3, longbow); Full Atk +3 melee (1d8+1/x3, warhammer) or +1 ranged (1d8/x3, longbow); Space/Reach 5 ft./5 ft.; SA -; SQ Repletion, resilience, resistance; AL N; SV Fort +3, Ref +0, Will -1; Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 6\n\nSkills and Feats: Climb +3, Jump +3; Weapon Focus (warhammer)','\n      <div topic=\"Elan\" level=\"2\"><p><h2>Elan</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Elan, 1st-Level Warrior<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Aberration (Psionic)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d8+1 (5 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (+3 studded leather, +1 light shield), touch 10, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Warhammer +3 melee (1d8+1/x3) or longbow +1 ranged (1d8/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Warhammer +3 melee (1d8+1/x3) or longbow +1 ranged (1d8/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Repletion, resilience, resistance<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +0, Will -1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +3, Jump +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Focus (warhammer)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Congregate (2-4), squad (11-20 plus 2 3rdlevel sergeants and 1 leader of 3rd-6th level), or band (30-100 plus 150% noncombatants plus 1 3rd-level sergeant per 10 adults, 5 5thlevel lieutenants, and 3 7thlevel captains)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n</table><p>Elans typically stand just under 6 feet tall and weigh in the neighborhood of 180 pounds, with men sometimes taller and heavier than women, but not always.</p><p>Elans speak Common.</p><p>Most elans are psions or psychic warriors.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Repletion\" level=\"8\"><p><b>Repletion (Su):</b> By expending 1 power point, an elan does not need to eat or drink for 24 hours.</p>\n</div><div topic=\"Resilience\" level=\"8\"><p><b>Resilience (Su):</b> As an immediate action, an elan can reduce the damage he is about to take by 2 points for every 1 power point spent.</p>\n</div><div topic=\"Resistance\" level=\"8\"><p><b>Resistance (Su):</b> As an immediate action, an &#xE9;lan can spent 1 power point to gain a +4 racial bonus on saving throws until the beginning of his next turn.</p><p>The elan warrior presented here had the following ability scores before racial adjustments: Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8.</p>\n</div>\n</div><div topic=\"Elans as Characters\" level=\"3\"><p><h3>Elans as Characters</h3></p><p>Elan characters possess the following racial traits.</p><ul>\n <li>-2 Charisma.</li>\n <li>Medium size.</li>\n <li>Elan base land speed is 30 feet.</li>\n <li>No darkvision.</li>\n <li>Naturally Psionic: Elans gain 2 bonus power points at 1st level.</li>\n <li>Special Qualities (see above): Repletion, resilience, resistance.</li>\n <li>Automatic Languages: Common.</li>\n <li>Favored Class: Psion.</li>\n <li>Level Adjustment: +0.</li>\n</ul><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (665,'Folugub','Folugub',NULL,'Medium','Aberration',NULL,'4d8+12 (30 hp)','+3','40 ft. (8 squares)','18 (+3 Dex, +5 natural), touch 13, flat-footed 15','+3','+3','Tongue +6 melee touch (liquefy crystal)','Tongue +6 melee touch (liquefy crystal) and bite +1 melee (2d4)','5 ft.','5 ft.','Liquefy crystal','Darkvision 60 ft., scent','Fort +4, Ref +4, Will +5','Str 10, Dex 17, Con 17, Int 2, Wis 13, Cha 11','Listen +6, Move Silently +4, Spot +6',NULL,'Alertness, Weapon Finesse',NULL,'Underground','Solitary or pair','2','None','Always neutral','5-6 HD (Medium); 7-14 HD (Large)','-','Liquefy Crystal (Ex)','Folugub; CR 2; Medium aberration; HD 4d8+12; hp 30; Init +3; Spd 40 ft. (8 squares); AC 18 (+3 dex, +5 natural), touch 13, flat-footed 15; Base Atk +3; Grp +3; Atk +6 melee (liquefy crystal, tongue); Full Atk +6 melee (liquefy crystal, tongue) and +1 melee (2d4, bite); Space/Reach 5 ft./5 ft.; SA Liquefy crystal; SQ Darkvision 60 ft., scent; AL N; SV Fort +4, Ref +4, Will +5; Str 10, Dex 17, Con 17, Int 2, Wis 13, Cha 11\n\nSkills and Feats: Listen +6, Move Silently +4, Spot +6; Alertness, Weapon Finesse','\n      <div topic=\"Folugub\" level=\"2\"><p><h2>Folugub</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Folugub</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Aberration<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>4d8+12 (30 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>18 (+3 Dex, +5 natural), touch 13, flat-footed 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+3/+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Tongue +6 melee touch (liquefy crystal)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Tongue +6 melee touch (liquefy crystal) and bite +1 melee (2d4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Liquefy crystal<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +4, Ref +4, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 10, Dex 17, Con 17, Int 2, Wis 13, Cha 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +6, Move Silently +4, Spot +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Weapon Finesse<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or pair<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>5-6 HD (Medium); 7-14 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A folugub can scent a crystal object up to 90 feet away, and once it has the scent, little deters it from its goal. It usually ceases attacking to devour a freshly liquefied crystal. The creature targets the largest crystal object available.</p><div topic=\"Liquefy Crystal\" level=\"8\"><p><b>Liquefy Crystal (Ex):</b> A folugub that makes a successful touch attack with its tongue causes the target crystal to change phase, turning immediately from solid to liquid and becoming worthless. The touch can destroy up to a 5-foot cube of crystal instantly. Magic or psionic items made of crystal (including crystalline armor and weapons) must succeed on a DC 19 Reflex save or be liquefied. The save DC is Constitution-based and includes a +4 racial modifier.</p><p>A crystalline weapon that deals damage to a folugub becomes liquefied immediately.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (666,'Gray Glutton','Gray Glutton',NULL,'Huge','Magical Beast',NULL,'9d10+36 (85 hp)','-1','40 ft. (8 squares)','20 (-2 size, -1 Dex, +13 natural), touch 7, flat-footed 20','+9','+25','Bite +15 melee (2d8+8)','Bite +15 melee (2d8+8) and 2 claws +10 melee (2d6+4)','15 ft.','10 ft.','Null psionic exhalation','Darkvision 60 ft., low-light vision, power resistance 20, scent','Fort +10, Ref +5, Will +7','Str 27, Dex 9, Con 19, Int 2, Wis 15, Cha 20','Jump +14, Listen +7, Spot +3','Track','Closed Mind, Hostile Mind, Iron Will, Psionic Hole',NULL,'Underground','Solitary, pair, or cluster (3-5)','7','None','Always neutral','10-20 HD (Huge); 21-27 HD (Gargantuan)','-','Null Psionic Exhalation (Su)','Gray glutton; CR 7; Huge magical beast; HD 9d10+36; hp 85; Init -1; Spd 40 ft. (8 squares); AC 20 (-2 size, -1 dex, +13 natural), touch 7, flat-footed 20; Base Atk +9; Grp +25; Atk +15 melee (2d8+8, bite); Full Atk +15 melee (2d8+8, bite) and +10 melee (2d6+4, 2 claws); Space/Reach 15 ft./10 ft.; SA Null psionic exhalation; SQ Darkvision 60 ft., low-light vision, power resistance 20, scent; AL N; SV Fort +10, Ref +5, Will +7; Str 27, Dex 9, Con 19, Int 2, Wis 15, Cha 20\n\nSkills and Feats: Jump +14, Listen +7, Spot +3; Closed Mind, Hostile Mind, Iron Will, Psionic Hole, Track','\n      <div topic=\"Gray Glutton\" level=\"2\"><p><h2>Gray Glutton</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Gray Glutton</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Huge Magical Beast<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>9d10+36 (85 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>-1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>20 (-2 size, -1 Dex, +13 natural), touch 7, flat-footed 20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+9/+25<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +15 melee (2d8+8)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +15 melee (2d8+8) and 2 claws +10 melee (2d6+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Null psionic exhalation<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., low-light vision, power resistance 20, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +10, Ref +5, Will +7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 27, Dex 9, Con 19, Int 2, Wis 15, Cha 20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Jump +14, Listen +7, Spot +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Closed Mind, Hostile Mind, Iron Will, Psionic Hole, Track <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, or cluster (3-5)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>10-20 HD (Huge); 21-27 HD (Gargantuan)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A gray glutton attacks anything psionic, or anything that stands in its way of tracking down new psionic prey. Of course, a gray glutton has to eat-and eat a lot to feed its bulk-so when not on the scent it will attack any living creature. It always breaks off attacks against nonpsionic foes if psionic prey is an option. The only creatures it refuses to eat are elves (and it dislikes the taste of dwarves). No challenge seems too extreme to it, even if that means bulling into the center of a powerful party of manifesters.</p><div topic=\"Null Psionic Exhalation\" level=\"8\"><p><b>Null Psionic Exhalation (Su):</b> As a free action, a gray glutton can breathe forth a cloud of pale blue translucent gas into an adjacent 10-foot cube. The gas is psionically poisonous; the initial damage is 1d4 power points, and the secondary damage is 3d4 power points (Fortitude DC 18 negates). Affected psionic characters and creatures subtract the lost power points from their reserves.</p><p>The save DC is Constitution-based.</p><p>Once a gray glutton has used its exhalation, it must wait 4 rounds before it can exhale again.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (667,'Half-Giant','Half-Giant, 1st-Level Warrior',NULL,'Medium','Giant','Psionic','1d8+2 (6 hp)','-1','30 ft. (6 squares)','13 (-1 Dex, +4 scale mail), touch 9, flat-footed 13','+1','+7','Large greatsword +4 melee (3d6+3/19-20) or Large javelin +0 ranged (1d8+2)','Large greatsword +4 melee (3d6+3/19-20) or Large javelin +0 ranged (1d8+2)','5 ft.','5 ft.','Psi-like abilities','Fire acclimated, giant\'s stature, low-light vision','Fort +4, Ref -1, Will -1','Str 15, Dex 9, Con 14, Int 10, Wis 9, Cha 8','Listen +1, Spot +1',NULL,'Weapon Focus (greatsword)',NULL,'Warm desert','Team (2-4), squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level), or band (30-100 plus 150% noncombatants plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)','1','Standard','Usually neutral good','By character class','+1','Fire Acclimated (Ex), Powerful Build (Ex)','1st-level warrior half-giant; CR 1; Medium giant (psionic); HD 1d8+2; hp 6; Init -1; Spd 30 ft. (6 squares); AC 13 (-1 dex, +4 scale mail), touch 9, flat-footed 13; Base Atk +1; Grp +7; Atk +4 melee (3d6+3/19-20, large greatsword) or +0 ranged (1d8+2, large javelin); Full Atk +4 melee (3d6+3/19-20, large greatsword) or +0 ranged (1d8+2, large javelin); Space/Reach 5 ft./5 ft.; SA Psi-like abilities; SQ Fire acclimated, giant\'s stature, low-light vision; AL NG; SV Fort +4, Ref -1, Will -1; Str 15, Dex 9, Con 14, Int 10, Wis 9, Cha 8\n\nSkills and Feats: Listen +1, Spot +1; Weapon Focus (greatsword)','\n      <div topic=\"Half-Giant\" level=\"2\"><p><h2>Half-Giant</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Half-Giant, 1st-Level Warrior<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Giant (Psionic)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d8+2 (6 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>-1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>13 (-1 Dex, +4 scale mail), touch 9, flat-footed 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/+7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Large greatsword +4 melee (3d6+3/19-20) or Large javelin +0 ranged (1d8+2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Large greatsword +4 melee (3d6+3/19-20) or Large javelin +0 ranged (1d8+2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Psi-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Fire acclimated, giant\'s stature, low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +4, Ref -1, Will -1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 15, Dex 9, Con 14, Int 10, Wis 9, Cha 8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +1, Spot +1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Focus (greatsword)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm desert<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Team (2-4), squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level), or band (30-100 plus 150% noncombatants plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral good<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n</table><p>Half-giants typically stand from 7 feet to nearly 8 feet tall and weigh from 250 to 400 pounds, with men noticeably taller and heavier than women.</p><p>Half-giants speak Common. Many also learn Giant.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Because of their giant ancestry, half-giants are able to use weapons sized for creatures larger than normal humans. They gain considerable satisfaction in using these large weapons in combat against their foes.</p><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> 1/day: <i>stomp</i> (DC 10). Manifester level equal to 1/2 HD (minimum 1st). The save DC is Charisma-based.</p>\n</div><div topic=\"Fire Acclimated\" level=\"8\"><p><b>Fire Acclimated (Ex):</b> Half-giants have a +2 racial bonus on saving throws against all fire spells and effects.</p>\n</div><div topic=\"Powerful Build\" level=\"8\"><p><b>Powerful Build (Ex):</b> The physical stature of half-giants lets them function in many ways as if they were one size category larger. Whenever a half-giant is subject to a size modifier or special size modifier for an opposed check (such as during grapple checks, bull rush attempts, and trip attempts), the half-giant is treated as one size larger if doing so is advantageous to him. A half-giant is also considered to be one size larger when determining whether a creature\'s special attacks based on size (such as improved grab or swallow whole) can affect him. A half-giant can use weapons designed for a creature one size larger without penalty. However, his space and reach remain those of a creature of his actual size. The benefits of this racial trait stack with the effects of powers, abilities, and spells that change the subject\'s size category.</p><p>The half-giant warrior presented here had the following ability scores before racial adjustments: Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8.</p>\n</div>\n</div><div topic=\"Half-Giants as Characters\" level=\"3\"><p><h3>Half-Giants as Characters</h3></p><p>Half-giant characters possess the following racial traits.</p><ul>\n <li>+2 Constitution, +2 Strength, -2 Dexterity.</li>\n <li>Medium size.</li>\n <li>Half-giant base land speed is 30 feet.</li>\n <li>Low-light vision.</li>\n <li>Naturally Psionic: Half-giants gain 2 bonus power points at 1st level, regardless of whether they choose a psionic class.</li>\n <li>Fire Acclimated: Half-giants have a +2 racial bonus on saving throws against all fire spells and effects.</li>\n <li>Powerful build (see above).</li>\n <li>Special Attacks (see above): Psi-like abilities.</li>\n <li>Automatic Language: Common. Bonus Language: Draconic, Giant, Gnoll, Ignan.</li>\n <li>Favored Class: Psychic warrior.</li>\n <li>Level adjustment: +1.</li>\n</ul><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (668,'Intellect Devourer','Intellect Devourer',NULL,'Small','Aberration','Evil, Psionic','6d8+15 (42 hp)','+5','40 ft. (8 squares)','21 (+1 size, +5 Dex, +5 natural), touch 16, flat-footed 16','+4','+1','Claw +6 melee (1d3+1)','4 claws +6 melee (1d3+1)','5 ft.','5 ft.','Body thief, psi-like abilities','Blindsight 60 ft., damage reduction 10/adamantine, immunity to fire, power resistance 23, electricity resistance 15, vulnerability to protection from evil','Fort +4, Ref +7, Will +6','Str 13, Dex 21, Con 15, Int 12, Wis 12, Cha 14','Bluff + 15, Concentration +11 (+15 when manifesting defensively), Hide +14, Listen +14, Move Silently +16','Wild Talent','Combat Manifestation, Toughness, Up the Walls',NULL,'Underground','Solitary or pod (2-4)','7','1/2 coins; double goods; standard items','Always chaotic evil','7-8 HD (Small); 9-15 HD (Medium); 16-18 HD (Large)','+6','Blindsight (Ex), Body Thief (Su), Vulnerability to Protection from Evil (Ex)','Intellect devourer; CR 7; Small aberration (evil, psionic); HD 6d8+15; hp 42; Init +5; Spd 40 ft. (8 squares); AC 21 (+1 size, +5 dex, +5 natural), touch 16, flat-footed 16; Base Atk +4; Grp +1; Atk +6 melee (1d3+1, claw); Full Atk +6 melee (1d3+1, 4 claws); Space/Reach 5 ft./5 ft.; SA Body thief, psi-like abilities; SQ Blindsight 60 ft., damage reduction 10/adamantine, immunity to fire, power resistance 23, electricity resistance 15, vulnerability to protection from evil; AL CE; SV Fort +4, Ref +7, Will +6; Str 13, Dex 21, Con 15, Int 12, Wis 12, Cha 14\n\nSkills and Feats: Bluff + 15, Concentration +11 (+15 when manifesting defensively), Hide +14, Listen +14, Move Silently +16; Combat Manifestation, Toughness, Up the Walls, Wild Talent','\n      <div topic=\"Intellect Devourer\" level=\"2\"><p><h2>Intellect Devourer</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Intellect Devourer</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Aberration (Evil, Psionic)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>6d8+15 (42 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>21 (+1 size, +5 Dex, +5 natural), touch 16, flat-footed 16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+4/+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Claw +6 melee (1d3+1)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>4 claws +6 melee (1d3+1)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Body thief, psi-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Blindsight 60 ft., damage reduction 10/adamantine, immunity to fire, power resistance 23, electricity resistance 15, vulnerability to <i>protection from evil</i><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +4, Ref +7, Will +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 13, Dex 21, Con 15, Int 12, Wis 12, Cha 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Bluff + 15, Concentration +11 (+15 when manifesting defensively), Hide +14, Listen +14, Move Silently +16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Combat Manifestation, Toughness, Up the Walls, Wild Talent <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or pod (2-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>1/2 coins; double goods; standard items<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always chaotic evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>7-8 HD (Small); 9-15 HD (Medium); 16-18 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+6<br/></td>\n\n</tr>\n</table><p>Intellect devourers understand Common but must be in possession of a body to speak. An intellect devourer in possession of a body also knows the languages known by that victim.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Body Thief\" level=\"8\"><p><b>Body Thief (Su):</b> When an intellect devourer overcomes a lone victim, it consumes the victim\'s brain and enters the skull. As a full-round action that provokes attacks of opportunity, the devourer can merge its form with that of a helpless or dead creature of Small size or larger. The devourer cannot merge its body with that of a creature immune to extra damage from critical hits.</p><p>When an intellect devourer completes its merging, it psionically consumes the brain of the victim (which kills it if it is not already dead). The devourer can exit the body at any time as a standard action, bursting the victim\'s skull and resuming its normal form.</p><p>After consuming its victim\'s brain, an intellect devourer can instead choose to animate the body for up to seven days as if it were the victim\'s original brain. The devourer retains its hit points, saving throws, and mental ability scores, as well as its psi-like abilities. It assumes the physical qualities and ability scores of the victim, as if it had used <i>polymorph</i> to assume the victim\'s form. As long as the intellect devourer occupies the body, it knows the languages spoken by the victim and very basic information about the victim\'s identity and personality, but none of the victim\'s specific memories or knowledge.</p>\n</div><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> At will-<i>cloud mind</i>,  <i>compression</i>,  <i>detect psionics</i>,  <i>ego whip</i> (2d4, DC 16*), <i>empty mind</i> (+5 on Will saves*), <i>id insinuation</i> (three targets, DC 16*); 3/day-<i>body adjustment</i> (2d12*), <i>intellect fortress</i>,  <i>painful strike</i>. Manifester level 7th.</p><p>The save DCs are Charisma-based.</p><p>*Includes augmentation for the intellect devourer\'s manifester level.</p>\n</div><div topic=\"Blindsight\" level=\"8\"><p><b>Blindsight (Ex):</b> An intellect devourer can use nonvisual means to ascertain all foes within 60 feet as a sighted creature would.</p>\n</div><div topic=\"Vulnerability to Protection from Evil\" level=\"8\"><p><b>Vulnerability to Protection from Evil (Ex):</b> An intellect devourer is treated as a summoned creature for the purpose of determining how it is affected by a <i>protection from evil</i> spell.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Intellect devourers have a +8 racial bonus on Bluff checks, useful for passing off the possessed body as the original. They also have a +8 racial bonus on Move Silently checks and Listen checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (669,'Maenad','Maenad, 1st-Level Warrior',NULL,'Medium','Humanoid','Maenad, Psionic','1d8+1 (5 hp)','+0','30 ft. (6 squares)','14 (+3 studded leather, +1 light shield), touch 10, flat-footed 14','+1','+2','Longsword +3 melee (1d8+1/19-20) or longbow +1 ranged (1d8/x3)','Longsword +3 melee (1d8+1/19-20) or longbow +1 ranged (1d8/x3)','5 ft.','5 ft.','Psi-like abilities','Outburst','Fort +3, Ref +0, Will -1','Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8','Climb +3, Jump +3',NULL,'Weapon Focus (longsword)',NULL,'Warm hills','Party (2-4), squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level), or band (30-100 plus 150% noncombatants plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)','1/2','Standard','Usually neutral','By character class','+0','Outburst (Ex)','1st-level warrior maenad; CR 1/2; Medium humanoid (maenad, psionic); HD 1d8+1; hp 5; Init +0; Spd 30 ft. (6 squares); AC 14 (+3 studded leather, +1 light shield), touch 10, flat-footed 14; Base Atk +1; Grp +2; Atk +3 melee (1d8+1/19-20, longsword) or +1 ranged (1d8/x3, longbow); Full Atk +3 melee (1d8+1/19-20, longsword) or +1 ranged (1d8/x3, longbow); Space/Reach 5 ft./5 ft.; SA Psi-like abilities; SQ Outburst; AL N; SV Fort +3, Ref +0, Will -1; Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8\n\nSkills and Feats: Climb +3, Jump +3; Weapon Focus (longsword)','\n      <div topic=\"Maenad\" level=\"2\"><p><h2>Maenad</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Maenad, 1st-Level Warrior<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Humanoid (Maenad, Psionic)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d8+1 (5 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (+3 studded leather, +1 light shield), touch 10, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Longsword +3 melee (1d8+1/19-20) or longbow +1 ranged (1d8/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Longsword +3 melee (1d8+1/19-20) or longbow +1 ranged (1d8/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Psi-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Outburst<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +0, Will -1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +3, Jump +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Focus (longsword)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm hills<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Party (2-4), squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level), or band (30-100 plus 150% noncombatants plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n</table><p>Maenads typically stand more than 6 feet tall and weigh about 200 pounds; males are the same height as and only marginally heavier than maenad females. Maenads have no facial or body hair, and they prefer heavier clothing and armor if possible.</p><p>Maenads speak their own language and Common.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> 1/day-<i>energy ray</i>. A maenad can deal only sonic damage with this ability. Manifester level equal to 1/2 Hit Dice (minimum 1st). The save DC is Charisma-based.</p>\n</div><div topic=\"Outburst\" level=\"8\"><p><b>Outburst (Ex):</b> Once per day for up to 4 rounds a maenad can subjugate his mentality. He takes a -2 penalty to Intelligence and Wisdom but gains a +2 bonus to Strength.</p>\n</div>\n</div><div topic=\"Maenads as Characters\" level=\"3\"><p><h3>Maenads as Characters</h3></p><p>Maenad characters possess the following racial traits.</p><ul>\n <li>Medium size.</li>\n <li>Maenad base land speed is 30 feet.</li>\n <li>Naturally Psionic: Maenads gain 2 bonus power points at 1st level.</li>\n <li>Special Attacks (see above): Psi-like abilities.</li>\n <li>Special Qualities (see above): Outburst.</li>\n <li>Automatic Languages: Common, Maenad. Bonus Languages: Aquan, Draconic, Dwarven, Elven, Goblin.</li>\n <li>Favored Class: Wilder.</li>\n <li>Level Adjustment: +0.</li>\n</ul><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (670,'Neothelid','Neothelid',NULL,'Gargantuan','Aberration','Psionic','25d8+200 (312 hp)','+2','20 ft. (4 squares)','28 (-4 size, -2 Dex, +24 natural), touch 4, flat-footed 28','+18','+40','Tentacle rake +24 melee (2d6+10/19-20)','4 tentacle rakes +24 melee (2d6+10/19-20)','30 ft.','30 ft.','Breath weapon, improved grab, psi-like abilities, swallow whole','Blindsight 100 ft., damage reduction 5/-, power resistance 25','Fort +16, Ref +6, Will +16','Str 30, Dex 7, Con 27, Int 16, Wis 15, Cha 20','Climb +38, Knowledge (psionics) +31, Listen +30, Psicraft +31, Spot +30',NULL,'Cleave, Improved Critical (tentacle rake), Improved Initiative, Power Attack, Psionic Endowment, Psionic Fist, Psionic Meditation, Speed of Thought, Wild Talent',NULL,'Underground','Solitary','15','Standard','Always lawful evil','26-45 HD (Colossal)','-','Blindsight (Ex), Breath Weapon (Su), Improved Grab (Ex), Swallow Whole (Ex)','Neothelid; CR 15; Gargantuan aberration (psionic); HD 25d8+200; hp 312; Init +2; Spd 20 ft. (4 squares); AC 28 (-4 size, -2 dex, +24 natural), touch 4, flat-footed 28; Base Atk +18; Grp +40; Atk +24 melee (2d6+10/19-20, tentacle rake); Full Atk +24 melee (2d6+10/19-20, 4 tentacle rakes); Space/Reach 30 ft./30 ft.; SA Breath weapon, improved grab, psi-like abilities, swallow whole; SQ Blindsight 100 ft., damage reduction 5/-, power resistance 25; AL LE; SV Fort +16, Ref +6, Will +16; Str 30, Dex 7, Con 27, Int 16, Wis 15, Cha 20\n\nSkills and Feats: Climb +38, Knowledge (psionics) +31, Listen +30, Psicraft +31, Spot +30; Cleave, Improved Critical (tentacle rake), Improved Initiative, Power Attack, Psionic Endowment, Psionic Fist, Psionic Meditation, Speed of Thought, Wild Talent','\n      <div topic=\"Neothelid\" level=\"2\"><p><h2>Neothelid</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Neothelid</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Gargantuan Aberration (Psionic)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>25d8+200 (312 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>28 (-4 size, -2 Dex, +24 natural), touch 4, flat-footed 28<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+18/+40<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Tentacle rake +24 melee (2d6+10/19-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>4 tentacle rakes +24 melee (2d6+10/19-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>30 ft./30 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Breath weapon, improved grab, psi-like abilities, swallow whole<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Blindsight 100 ft., damage reduction 5/-, power resistance 25<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +16, Ref +6, Will +16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 30, Dex 7, Con 27, Int 16, Wis 15, Cha 20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +38, Knowledge (psionics) +31, Listen +30, Psicraft +31, Spot +30<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Cleave, Improved Critical (tentacle rake), Improved Initiative, Power Attack, Psionic Endowment, Psionic Fist, Psionic Meditation, Speed of Thought, Wild Talent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always lawful evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>26-45 HD (Colossal)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A mature neothelid is a gigantic worm scores of feet long and weighing tens of thousands of pounds. Although they understand Undercommon, they rarely communicate in a meaningful way.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Breath Weapon\" level=\"8\"><p><b>Breath Weapon (Su):</b> Cone of acid 50 feet long, once every 1d4 rounds; damage 14d10 acid, Reflex half DC 30.</p>\n</div><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a neothelid must hit a creature with two tentacles during the same attack. If it gets a hold, it automatically deals tentacle damage and can attempt to swallow the foe.</p>\n</div><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> At will-<i>body equilibrium</i>,  <i>psionic charm</i> (all targets, duration 15 days, DC 21*), <i>clairvoyant sense</i>,  <i>psionic levitate</i>,  <i>read thoughts</i> (DC 17*), <i>psionic suggestion</i> (seven targets, DC 17*), <i>telekinetic force</i> (500 lb., DC 18*), <i>telekinetic maneuver</i> (+4 bonus, DC 19*), <i>telekinetic thrust</i> (500 lb., DC 18*), <i>psionic teleport</i>,  <i>trace teleport</i>,  <i>truevenom</i> (DC 19); 3/day-<i>mind thrust</i> (15d10, DC 23*), <i>psychic thrust</i> (6d6, DC 16**). Manifester level 15th. The save DCs are Charisma-based.</p><p>*Includes augmentation for the neothelid\'s manifester level.</p><p>**Includes the inherent +4 save adjustment described in the power.</p>\n</div><div topic=\"Swallow Whole\" level=\"8\"><p><b>Swallow Whole (Ex):</b> A neothelid can try to swallow a grabbed opponent of a smaller size than itself by making a successful grapple check. Once inside, the opponent takes 2d8+15 points of crushing damage plus 2d6 points of acid damage per round from stomach secretions. A swallowed creature can cut its way out by using a light slashing or piercing weapon to deal 25 points of damage to the stomach (AC 22). Once the creature exits, muscular action closes the hole; another swallowed opponent must cut its own way out. A neothelid\'s interior can hold 1 Huge, 2 Large, 8 Medium, 32 Small, 128 Tiny, or 512 Diminutive or smaller opponents.</p>\n</div><div topic=\"Blindsight\" level=\"8\"><p><b>Blindsight (Ex):</b> A neothelid can use nonvisual means to ascertain all foes within 100 feet as a sighted creature would.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (671,'Phthisic','Phthisic',NULL,'Large','Monstrous Humanoid','Psionic','6d8+30 (57 hp)','+5','30 ft. (6 squares)','18 (-1 size, +1 Dex, +8 natural), touch 10, flat-footed 17','+6','+16','Claw +11 melee (1d6+6)','2 claws +11 melee (1d6+6) and bite +6 melee (1d6+3 plus mind feed)','10 ft.','10 ft.','Mind feed, psi-like abilities','Damage reduction 10/magic, darkvision 60 ft., regeneration 5, cold resistance 10, scent','Fort +9, Ref +6, Will +8','Str 23, Dex 12, Con 21, Int 10, Wis 16, Cha 16','Listen +11, Move Silently +7, Spot +11',NULL,'Alertness, Great Fortitude, Improved Initiative',NULL,'Any','Solitary or gang (2-4)','6','Standard','Always chaotic evil','7-12 HD (Large); 13-18 HD (Huge)','-','Mind Feed (Ex), Regeneration (Ex)','Phthisic; CR 6; Large monstrous humanoid (psionic); HD 6d8+30; hp 57; Init +5; Spd 30 ft. (6 squares); AC 18 (-1 size, +1 dex, +8 natural), touch 10, flat-footed 17; Base Atk +6; Grp +16; Atk +11 melee (1d6+6, claw); Full Atk +11 melee (1d6+6, 2 claws) and +6 melee (1d6+3 plus mind feed, bite); Space/Reach 10 ft./10 ft.; SA Mind feed, psi-like abilities; SQ Damage reduction 10/magic, darkvision 60 ft., regeneration 5, cold resistance 10, scent; AL CE; SV Fort +9, Ref +6, Will +8; Str 23, Dex 12, Con 21, Int 10, Wis 16, Cha 16\n\nSkills and Feats: Listen +11, Move Silently +7, Spot +11; Alertness, Great Fortitude, Improved Initiative','\n      <div topic=\"Phthisic\" level=\"2\"><p><h2>Phthisic</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Phthisic</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Monstrous Humanoid (Psionic)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>6d8+30 (57 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>18 (-1 size, +1 Dex, +8 natural), touch 10, flat-footed 17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+6/+16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Claw +11 melee (1d6+6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 claws +11 melee (1d6+6) and bite +6 melee (1d6+3 plus mind feed)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Mind feed, psi-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Damage reduction 10/magic, darkvision 60 ft., regeneration 5, cold resistance 10, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +9, Ref +6, Will +8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 23, Dex 12, Con 21, Int 10, Wis 16, Cha 16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +11, Move Silently +7, Spot +11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Great Fortitude, Improved Initiative<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or gang (2-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always chaotic evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>7-12 HD (Large); 13-18 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A phthisic stands 10 feet tall and weighs 600 pounds. It vaguely resembles the person whose mind the phthisic escaped from, but is severely distorted (someone who knows the individual from whom the phthisic sprung can make a DC 25 Spot check to note the resemblance).</p><p>A phthisic speaks the primary language of the mind that birthed it, usually Common.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Mind Feed\" level=\"8\"><p><b>Mind Feed (Ex):</b> A phthisic that hits with its bite attack deals 1d4 points of Intelligence damage. If this effect reduces the opponent\'s Intelligence score to 0, the ability damage becomes ability drain.</p>\n</div><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> 3/day-<i>brain lock</i> (affects animals, fey, giants, humanoids, magical beasts, and monstrous humanoids, DC 15*), <i>dimension slide</i>, <i>ego whip</i> (1d4, DC 15*),  <i>mental barrier</i>,  <i>mind thrust</i> (ML 4th, 4d10,  DC 15*), <i>skate</i>; 1/day-<i>body adjustment</i> (heal 1d12*), <i>catapsi</i> (DC 18). Manifester level 6th. The save DCs are Charisma-based.</p><p>*Includes augmentation for the phthisic\'s manifester level.</p>\n</div><div topic=\"Regeneration\" level=\"8\"><p><b>Regeneration (Ex):</b> Fire and acid deal normal damage to a phthisic.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (672,'Psicrystal','Psicrystal',NULL,'Diminutive','Construct',NULL,'As master\'s HD (hp 1/2 master\'s)','+2','30 ft. (6 squares), climb 20 ft.*','16 (+4 size, +2 Dex*), touch 16, flat-footed 14','+0','-17','-','-','1 ft.','0 ft.','-','Construct traits, hardness 8, psicrystal granted abilities (improved evasion, personality, self-propulsion, share powers, sighted, telepathic link)','As master\'s saves','Str 1*, Dex 15*, Con -, Int 6, Wis 10, Cha 10','Climb +14*, Listen +6, Move Silently +6, Search +2, Spot +6',NULL,'Alertness',NULL,'Any','Solitary','Included with master','None','As master','-','-','','Psicrystal; CR Included with master; Diminutive construct; HD As master\'s HD (hp 1/2 master\'s); Init +2; Spd 30 ft. (6 squares), climb 20 ft.*; AC 16 (+4 size, +2 dex*), touch 16, flat-footed 14; Base Atk +0; Grp -17; Atk -; Full Atk -; Space/Reach 1 ft./0 ft.; SA -; SQ Construct traits, hardness 8, psicrystal granted abilities (improved evasion, personality, self-propulsion, share powers, sighted, telepathic link); AL N; SV As master\'s saves; Str 1*, Dex 15*, Con -, Int 6, Wis 10, Cha 10\n\nSkills and Feats: Climb +14*, Listen +6, Move Silently +6, Search +2, Spot +6; Alertness','\n      <div topic=\"Psicrystal\" level=\"2\"><p><h2>Psicrystal</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Psicrystal</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Diminutive Construct<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>As master\'s HD (hp 1/2 master\'s)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares), climb 20 ft.*<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (+4 size, +2 Dex*), touch 16, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+0/-17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>1 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Construct traits, hardness 8, psicrystal granted abilities (improved evasion, personality, self-propulsion, share powers, sighted, telepathic link)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>As master\'s saves<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 1*, Dex 15*, Con -, Int 6, Wis 10, Cha 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +14*, Listen +6, Move Silently +6, Search +2, Spot +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>Included with master<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>As master<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">*With self-propulsion ability activated.<br/></td>\n\n</tr>\n</table><p>The psicrystal described here is that of a 1st-level manifester.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A psicrystal\'s characteristics depend on its master. Its Hit Dice are equal to its master\'s Hit Dice (counting only levels in psion or wilder), its hit points are equal to half its master\'s, and its saving throw bonuses are the same as its master\'s.</p><div topic=\"Construct Traits\" level=\"8\"><p><b>Construct Traits:</b> A psicrystal has immunity to poison, <i>sleep</i>,  paralysis, stunning, disease, death effects, necromancy effects, mind-affecting effects (charms, compulsions, phantasms, patterns, and morale effects), and any effect that requires a Fortitude save unless it also works on objects or is harmless. It is not subject to critical hits, nonlethal damage, ability damage, ability drain, fatigue, exhaustion, or energy drain. It cannot heal damage, but it can be repaired. Psicrystals do not have the usual construct traits of darkvision and low-light vision.</p>\n</div><div topic=\"Psicrystal Granted Abilities\" level=\"8\"><p><b>Psicrystal Granted Abilities:</b> The psicrystal described here has the special abilities of self-propulsion, alertness, improved evasion, share powers, telepathic link, sighted, and personality (If its master chooses not to activate the self-propulsion ability, the psicrystal reverts to a speed of 0 feet and has no Strength score and no Dexterity score.)</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A psicrystal (with its self-propulsion ability activated) uses its Dexterity modifier instead of its Strength modifier on Climb checks. It has a +8 racial bonus on Climb checks and can always choose to take 10, even if rushed or threatened.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (673,'Psion-Killer','Psion-Killer',NULL,'Large','Construct',NULL,'15d10+30 (112 hp)','+0','20 ft. (4 squares)','28 (-1 size, +19 natural), touch 9, flat-footed 28','+11','+25','Slam +20 melee (2d10+10)','2 slams +20 melee (2d10+10)','10 ft.','10 ft.','Dispel psionics','Construct traits, damage reduction 10/adamantine, darkvision 60 ft., immunity to psionics, low-light vision','Fort +5, Ref +5, Will +5','Str 31, Dex 10, Con -, Int -, Wis 11, Cha 1','-',NULL,'-',NULL,'Any','Solitary or gang (2-4)','12','None','Always neutral','16-21 HD (Large); 22-45 (Huge)','-','Dispel Psionics (Su), Immunity to Psionics (Ex)','Psion-killer; CR 12; Large construct; HD 15d10+30; hp 112; Init +0; Spd 20 ft. (4 squares); AC 28 (-1 size, +19 natural), touch 9, flat-footed 28; Base Atk +11; Grp +25; Atk +20 melee (2d10+10, slam); Full Atk +20 melee (2d10+10, 2 slams); Space/Reach 10 ft./10 ft.; SA Dispel psionics; SQ Construct traits, damage reduction 10/adamantine, darkvision 60 ft., immunity to psionics, low-light vision; AL N; SV Fort +5, Ref +5, Will +5; Str 31, Dex 10, Con -, Int -, Wis 11, Cha 1\n\nSkills and Feats: -; -','\n      <div topic=\"Psion-Killer\" level=\"2\"><p><h2>Psion-Killer</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Psion-Killer</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Construct<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>15d10+30 (112 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>28 (-1 size, +19 natural), touch 9, flat-footed 28<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+11/+25<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Slam +20 melee (2d10+10)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 slams +20 melee (2d10+10)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Dispel psionics<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Construct traits, damage reduction 10/adamantine, darkvision 60 ft., immunity to psionics, low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +5, Ref +5, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 31, Dex 10, Con -, Int -, Wis 11, Cha 1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or gang (2-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>16-21 HD (Large); 22-45 (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A psion-killer (also called a crystal golem) is 9-1/2 feet tall and weighs around 2,500 pounds. Its body is composed of sharply faceted crystal.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A psion-killer does nothing without explicit orders from its creator. It follows instructions literally and is incapable of any strategy or tactics. Psion-killers don\'t use weapons, even if ordered to, but always strike with their fists.</p><p>A psion-killer\'s creator can command it if the psion-killer is within 60 feet and can see and hear its creator. If uncommanded, a psion-killer usually follows its last instruction to the best of its ability, though if attacked it returns the attack. Its creator can give a psion-killer a simple command to govern its actions in his or her absence.</p><div topic=\"Dispel Psionics\" level=\"8\"><p><b>Dispel Psionics (Su):</b> A psion-killer can use <i>dispel psionics</i> as a free action once per round. The effect is as an area dispel in a 30-foot-radius burst. The dispel check is 1d20+10.</p>\n</div><div topic=\"Construct Traits\" level=\"8\"><p><b>Construct Traits:</b> A psion-killer has immunity to poison, <i>sleep</i> effects, paralysis, stunning, disease, death effects, necromancy effects, mind-affecting effects (charms, compulsions, phantasms, patterns, and morale effects), and any effect that requires a Fortitude save unless it also works on objects or is harmless. It is not subject to critical hits, nonlethal damage, ability damage, ability drain, fatigue, exhaustion, or energy drain. It cannot heal damage, but it can be repaired.</p>\n</div><div topic=\"Immunity to Psionics\" level=\"8\"><p><b>Immunity to Psionics (Ex):</b> Psion-killers completely resist psionic effects that are subject to power resistance.</p>\n</div>\n</div><div topic=\"Construction\" level=\"3\"><p><h3>Construction</h3></p><p>A psion-killer\'s body is constructed from massive blocks of quartz crystal with a total weight of at least 5,000 pounds and costing at least 8,000 gp. Assembling the body requires a DC 20 Craft (sculpting) check or a DC 20 Craft (stonemasonry) check.</p><p>ML 16th; Craft Psionic Construct, <i>bend reality</i>, <i>dispel psionics</i>, <i>fabricate</i>, <i>mind seed</i>, manifester must be at least 16th level; Price 150,000 gp; Cost 79,000 gp + 5,680 XP.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (674,'Puppeteer','Puppeteer',NULL,'Fine','Magical Beast','Psionic','1/4 d10 (1 hp)','+2','5 ft. (1 square)','20 (+8 size, +2 Dex), touch 20, flat-footed 18','+1','-20','Bite +4 melee (1d2-5)','Bite +4 melee (1d2-5)','1/2 ft.','0 ft.','Enthrall, psi-like abilities','Blindsight 60 ft., host protection, telepathy 20 ft.','Fort +2, Ref +4, Will +5','Str 1, Dex 15, Con 11, Int 14, Wis 16, Cha 14','Hide +22, Listen +7, Sense Motive +7, Spot +7',NULL,'Iron Will',NULL,'Underground','Solitary or pack (2-8)','1','None','Usually lawful evil','-','-','Blindsight (Ex), Enthrall (Ex), Hide Mind (Su), Host Protection (Ex), Telepathy (Su)','Puppeteer; CR 1; Fine magical beast (psionic); HD 1/4 d10; hp 1; Init +2; Spd 5 ft. (1 square); AC 20 (+8 size, +2 dex), touch 20, flat-footed 18; Base Atk +1; Grp -20; Atk +4 melee (1d2-5, bite); Full Atk +4 melee (1d2-5, bite); Space/Reach 1/2 ft./0 ft.; SA Enthrall, psi-like abilities; SQ Blindsight 60 ft., host protection, telepathy 20 ft.; AL LE; SV Fort +2, Ref +4, Will +5; Str 1, Dex 15, Con 11, Int 14, Wis 16, Cha 14\n\nSkills and Feats: Hide +22, Listen +7, Sense Motive +7, Spot +7; Iron Will','\n      <div topic=\"Puppeteer\" level=\"2\"><p><h2>Puppeteer</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Puppeteer</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Fine Magical Beast (Psionic)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1/4 d10 (1 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>5 ft. (1 square)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>20 (+8 size, +2 Dex), touch 20, flat-footed 18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/-20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +4 melee (1d2-5)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +4 melee (1d2-5)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>1/2 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Enthrall, psi-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Blindsight 60 ft., host protection, telepathy 20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +2, Ref +4, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 1, Dex 15, Con 11, Int 14, Wis 16, Cha 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +22, Listen +7, Sense Motive +7, Spot +7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Iron Will<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or pack (2-8)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually lawful evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Puppeteers do not speak, though they can speak indirectly using a host body\'s vocal cords, in whatever language the host knows (usually Common).</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Puppeteers use their psionic powers in conjunction with their enthrall ability to gain control over potential hosts. Once it is in control, a puppeteer almost exclusively relies on the host\'s mental and physical abilities, although it can use its own powers to enhance their effectiveness in a particularly dangerous situation.</p><div topic=\"Enthrall\" level=\"8\"><p><b>Enthrall (Ex):</b> If a puppeteer is in physical contact with a person it has charmed (the puppeteer establishes a physical hold by means of slender infiltrating tendrils), the subject acts as if dominated. (Puppeteers often seek to charm victims first and then \'ask\' to be picked up.) So long as the puppeteer remains in contact with the victim, the domination remains in effect, even if a check would normally indicate that the effect is broken.</p>\n</div><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> 3/day- <i>detect psionics</i>,  <i>mental barrier</i>,  <i>psionic charm</i> (DC 13). Manifester level 1st. The save DCs are Charisma-based.</p>\n</div><div topic=\"Blindsight\" level=\"8\"><p><b>Blindsight (Ex):</b> A puppeteer can ascertain creatures by nonvisual means within 60 feet.</p>\n</div><div topic=\"Hide Mind\" level=\"8\"><p><b>Hide Mind (Su):</b> A puppeteer cannot be identified as psionic by divination spells or clairsentience powers.</p>\n</div><div topic=\"Host Protection\" level=\"8\"><p><b>Host Protection (Ex):</b> A puppeteer in control of a host is treated as an attended magic item for the purpose of making saving throws, even if the puppeteer is specifically targeted. A puppeteer that is attached to its host is treated as a creature in a grapple for the purpose of striking at the puppeteer instead of the host (but the host is not considered grappled in turn).</p>\n</div><div topic=\"Telepathy\" level=\"8\"><p><b>Telepathy (Su):</b> A puppeteer can communicate telepathically with any creature within 20 feet that has a language.</p><p/>\n</div>\n</div><div topic=\"Puppeteer, Flesh Harrower\" level=\"3\"><p><h3>Puppeteer, Flesh Harrower</h3></p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> 3/day-<i>concealing amorpha</i>, <i>hustle</i>, <i>mental barrier</i>; 1/day-<i>vigor</i> (+15 hp*). Manifester level 3rd.</p><p>*Includes augmentation for the flesh harrower\'s manifester level.</p><p/>\n</div>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (675,'Puppeteer','Puppeteer, Flesh Harrower',NULL,'Small','Magical Beast','Psionic','3d10+15 (31 hp)','+3','20 ft. (4 squares)','16 (+3 Dex, +3 natural), touch 13, flat-footed 13','+3','+1','Bite +6 melee (1d6+2)','Bite +6 melee (1d6+2) and 2 tail blades +1 melee (1d4+1)','5 ft.','5 ft.','Psi-like abilities','Blindsight 60 ft., telepathy 20 ft.','Fort +8, Ref +6, Will +4','Str 14, Dex 17, Con 21, Int 11, Wis 12, Cha 12','Hide +10, Move Silently +6, Listen +6, Spot +6',NULL,'Alertness, Iron Will',NULL,'Underground','Solitary or cluster (2-5)','2','None','Always neutral','4-6 HD (Small); 7-9 HD (Medium)','-','Blindsight (Ex), Enthrall (Ex), Hide Mind (Su), Host Protection (Ex), Telepathy (Su)','Flesh harrower puppeteer; CR 2; Small magical beast (psionic); HD 3d10+15; hp 31; Init +3; Spd 20 ft. (4 squares); AC 16 (+3 dex, +3 natural), touch 13, flat-footed 13; Base Atk +3; Grp +1; Atk +6 melee (1d6+2, bite); Full Atk +6 melee (1d6+2, bite) and +1 melee (1d4+1, 2 tail blades); Space/Reach 5 ft./5 ft.; SA Psi-like abilities; SQ Blindsight 60 ft., telepathy 20 ft.; AL N; SV Fort +8, Ref +6, Will +4; Str 14, Dex 17, Con 21, Int 11, Wis 12, Cha 12\n\nSkills and Feats: Hide +10, Move Silently +6, Listen +6, Spot +6; Alertness, Iron Will','\n      <div topic=\"Puppeteer, Flesh Harrower\" level=\"3\"><p><h3>Puppeteer, Flesh Harrower</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Puppeteer, Flesh Harrower</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Magical Beast (Psionic)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>3d10+15 (31 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (+3 Dex, +3 natural), touch 13, flat-footed 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+3/+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +6 melee (1d6+2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +6 melee (1d6+2) and 2 tail blades +1 melee (1d4+1)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Psi-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Blindsight 60 ft., telepathy 20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +8, Ref +6, Will +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 14, Dex 17, Con 21, Int 11, Wis 12, Cha 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +10, Move Silently +6, Listen +6, Spot +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Iron Will<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or cluster (2-5)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>4-6 HD (Small); 7-9 HD (Medium)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> 3/day-<i>concealing amorpha</i>, <i>hustle</i>, <i>mental barrier</i>; 1/day-<i>vigor</i> (+15 hp*). Manifester level 3rd.</p><p>*Includes augmentation for the flesh harrower\'s manifester level.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (676,'Temporal Filcher','Temporal Filcher',NULL,'Large','Aberration','Psionic','8d8+16 (52 hp)','+7','40 ft. (8 squares)','15 (-1 size, +3 Dex, +3 natural), touch 12, flat-footed 12','+6','+11','Claw +6 melee (1d6+1)','4 claws +6 melee (1d6+1) and bite +1 melee (1d8) and horn +1 melee (1d4)','10 ft.','10 ft.','Improved grab, psi-like abilities, time filch','Darkvision 60 ft.','Fort +4, Ref +5, Will +7','Str 13, Dex 17, Con 14, Int 7, Wis 12, Cha 14','Listen +7, Spot +7, Tumble +6',NULL,'Alertness, Dodge, Improved Initiative',NULL,'Any','Solitary','3','Standard','Usually evil (any)','9-15 HD (Large)','-','Improved Grab (Ex), Time Filch (Su)','Temporal filcher; CR 3; Large aberration (psionic); HD 8d8+16; hp 52; Init +7; Spd 40 ft. (8 squares); AC 15 (-1 size, +3 dex, +3 natural), touch 12, flat-footed 12; Base Atk +6; Grp +11; Atk +6 melee (1d6+1, claw); Full Atk +6 melee (1d6+1, 4 claws) and +1 melee (1d8, bite) and +1 melee (1d4, horn); Space/Reach 10 ft./10 ft.; SA Improved grab, psi-like abilities, time filch; SQ Darkvision 60 ft.; AL NE; SV Fort +4, Ref +5, Will +7; Str 13, Dex 17, Con 14, Int 7, Wis 12, Cha 14\n\nSkills and Feats: Listen +7, Spot +7, Tumble +6; Alertness, Dodge, Improved Initiative','\n      <div topic=\"Temporal Filcher\" level=\"2\"><p><h2>Temporal Filcher</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Temporal Filcher</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Aberration (Psionic)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>8d8+16 (52 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (-1 size, +3 Dex, +3 natural), touch 12, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+6/+11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Claw +6 melee (1d6+1)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>4 claws +6 melee (1d6+1) and bite +1 melee (1d8) and horn +1 melee (1d4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Improved grab, psi-like abilities, time filch<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +4, Ref +5, Will +7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 13, Dex 17, Con 14, Int 7, Wis 12, Cha 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +7, Spot +7, Tumble +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Dodge, Improved Initiative<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually evil (any)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>9-15 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Temporal filchers do not speak.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a temporal filcher must hit a creature of Large size or smaller with two claw attacks. It can then attempt to start a grapple as a free action without provoking attacks of opportunity. If it wins the grapple check, it establishes a hold and uses its time filch ability.</p>\n</div><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> At will-<i>chameleon</i>, <i>distract</i> (DC 13), <i>psionic dimension door</i>, <i>psionic levitate</i>, <i>wall walker</i>; 3/day-<i>mental barrier</i>. Manifester level 8th. The save DC is Charisma-based.</p>\n</div><div topic=\"Time Filch\" level=\"8\"><p><b>Time Filch (Su):</b> If a temporal filcher successfully grapples a Large or smaller creature, it latches onto the opponent\'s body and shifts 7 minutes forward in time as a free action. Observers (if any) see the temporal filcher and its prey disappear in a shimmer, then reappear 7 minutes later in exactly the orientation and condition they left. For the filcher and its prey, no time passes at all. The victim must succeed on a Will save (DC 16) or be dazed for 1 round from temporal disorientation. The ability is otherwise identical to <i>time hop</i> manifested by an 8th-level manifester.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (677,'Thought Eater','Thought Eater',NULL,'Small','Aberration','Psionic','3d8 (13 hp)','+8','40 ft. (8 squares)','17 (+1 size, +4 Dex, +2 natural), touch 15, flat-footed 13','+2','-1','+4 melee touch (eat thoughts)','+4 melee touch (eat thoughts)','5 ft.','5 ft.','Eat thoughts, psi-like abilities','Darkvision 60 ft., ethereal jaunt','Fort +1, Ref +5, Will +4','Str 12, Dex 18, Con 11, Int 7, Wis 12, Cha 14','Hide +10, Listen +5, Spot +5',NULL,'Alertness, Improved Initiative',NULL,'Ethereal Plane','Solitary or group (1-3)','2','None','Usually neutral','4-6 HD (Small)','-','Eat Thoughts (Su), Ethereal Jaunt (Su)','Thought eater; CR 2; Small aberration (psionic); HD 3d8; hp 13; Init +8; Spd 40 ft. (8 squares); AC 17 (+1 size, +4 dex, +2 natural), touch 15, flat-footed 13; Base Atk +2; Grp -1; Atk +4 melee (eat thoughts); Full Atk +4 melee (eat thoughts); Space/Reach 5 ft./5 ft.; SA Eat thoughts, psi-like abilities; SQ Darkvision 60 ft., ethereal jaunt; AL N; SV Fort +1, Ref +5, Will +4; Str 12, Dex 18, Con 11, Int 7, Wis 12, Cha 14\n\nSkills and Feats: Hide +10, Listen +5, Spot +5; Alertness, Improved Initiative','\n      <div topic=\"Thought Eater\" level=\"2\"><p><h2>Thought Eater</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Thought Eater</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Aberration (Psionic)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>3d8 (13 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>17 (+1 size, +4 Dex, +2 natural), touch 15, flat-footed 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+2/-1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>+4 melee touch (eat thoughts)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>+4 melee touch (eat thoughts)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Eat thoughts, psi-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., ethereal jaunt<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +1, Ref +5, Will +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 12, Dex 18, Con 11, Int 7, Wis 12, Cha 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +10, Listen +5, Spot +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Improved Initiative<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Ethereal Plane<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or group (1-3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>4-6 HD (Small)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Thought eaters do not speak.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A thought eater can spend a maximum of 10 continuous rounds on the Material Plane before its wispy flesh finally dissipates and it falls dead. If badly wounded, it escapes to the Ethereal Plane rather than continuing the fight.</p><div topic=\"Eat Thoughts\" level=\"8\"><p><b>Eat Thoughts (Su):</b> A thought eater can drain psionic power points with a successful melee touch attack. Each touch drains 6 power points from the opponent (or fewer, if the opponent has fewer than 6 points remaining). Against a nonpsionic creature or a psionic creature that currently has no power points, this touch attack instead deals 1 point of Intelligence damage, which provides nourishment equivalent to 6 power points.</p><p>A thought eater requires 12 power points per day to survive but will gorge itself on weak prey.</p>\n</div><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> At will-<i>detect psionics</i>, <i>distract</i> (DC 13), <i>precognition</i>,  <i>psionic daze</i> (DC 13*); 3/day-<i>thought shield</i>. </p><p>Manifester level 3rd. The save DCs are Charisma-based.</p><p>*Includes augmentation for the thought eater\'s manifester level.</p>\n</div><div topic=\"Ethereal Jaunt\" level=\"8\"><p><b>Ethereal Jaunt (Su):</b> A thought eater can shift from the Ethereal Plane to the Material Plane as part of any move action, and then shift back again as a free action. The ability is otherwise identical to the <i>psionic ethereal jaunt</i> power.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (678,'Thought Slayer','Thought Slayer',NULL,'Huge','Aberration','Psionic','14d8+70 (133 hp)','+1','50 ft. (10 squares)','23 (-2 size, +1 Dex, +14 natural), touch 9, flat-footed 22','+10','+26','Bite +17 melee (3d6+12)','Bite +17 melee (3d6+12)','15 ft.','15 ft.','Mind-consuming gaze, psi-like abilities','Darkvision 60 ft., ethereal jaunt, power resistance 21','Fort +11, Ref +5, Will +10','Str 26, Dex 13, Con 21, Int 7, Wis 12, Cha 15','Climb +12, Jump +20, Listen +7, Spot +8',NULL,'Alertness, Cleave, Great Fortitude, Power Attack, Weapon Focus (bite)',NULL,'Ethereal Plane','Solitary or pack (2-4)','13','Standard','Often chaotic neutral','15-28 HD (Huge)','-','Ethereal Jaunt (Su), Mind-Consuming Gaze (Su)','Thought slayer; CR 13; Huge aberration (psionic); HD 14d8+70; hp 133; Init +1; Spd 50 ft. (10 squares); AC 23 (-2 size, +1 dex, +14 natural), touch 9, flat-footed 22; Base Atk +10; Grp +26; Atk +17 melee (3d6+12, bite); Full Atk +17 melee (3d6+12, bite); Space/Reach 15 ft./15 ft.; SA Mind-consuming gaze, psi-like abilities; SQ Darkvision 60 ft., ethereal jaunt, power resistance 21; AL CN; SV Fort +11, Ref +5, Will +10; Str 26, Dex 13, Con 21, Int 7, Wis 12, Cha 15\n\nSkills and Feats: Climb +12, Jump +20, Listen +7, Spot +8; Alertness, Cleave, Great Fortitude, Power Attack, Weapon Focus (bite)','\n      <div topic=\"Thought Slayer\" level=\"2\"><p><h2>Thought Slayer</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Thought Slayer</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Huge Aberration (Psionic)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>14d8+70 (133 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>50 ft. (10 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>23 (-2 size, +1 Dex, +14 natural), touch 9, flat-footed 22<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+10/+26<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +17 melee (3d6+12)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +17 melee (3d6+12)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./15 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Mind-consuming gaze, psi-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., ethereal jaunt, power resistance 21<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +11, Ref +5, Will +10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 26, Dex 13, Con 21, Int 7, Wis 12, Cha 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +12, Jump +20, Listen +7, Spot +8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Cleave, Great Fortitude, Power Attack, Weapon Focus (bite)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Ethereal Plane<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or pack (2-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Often chaotic neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>15-28 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Thought slayers do not speak.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A thought slayer can spend a maximum of 10 continuous minutes on the Material Plane before its wispy flesh finally dissipates and it falls dead. If badly wounded, it escapes to the Ethereal Plane rather than continuing the fight.</p><div topic=\"Mind-Consuming Gaze\" level=\"8\"><p><b>Mind-Consuming Gaze (Su):</b> Instantly kill (by draining the mind away), range 30 feet, Fortitude DC 19 negates. The save DC is Charisma-based. This is considered a mind-affecting death effect. If a thought slayer\'s gaze is met indirectly (such as through a mirror or a reflection in water), the opponent does not die on a failed save but instead is dazed for 14 rounds. This otherwise is a gaze effect.</p><p>The gaze cannot affect creatures on the Material Plane while the thought slayer remains ethereal, but it can affect ethereal creatures while the thought slayer is on the Material Plane.</p>\n</div><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> At will-<i>brain lock</i> (any nonmindless, DC 14*), <i>chameleon</i>, <i>detect psionics</i>, <i>distract</i> (DC 13); 3/day-<i>body adjustment</i> (5d12*), <i>mental barrier</i> (+6 AC, 2 rounds*),  <i>mind trap</i> (10 rounds*), <i>precognition</i>, <i>wall walker</i>; 1/day-<i>escape detection</i>. Manifester level 14th. The save DCs are Charisma-based.</p><p>*Includes augmentation for the thought slayer\'s manifester level.</p>\n</div><div topic=\"Ethereal Jaunt\" level=\"8\"><p><b>Ethereal Jaunt (Su):</b> A thought slayer can shift from the Ethereal Plane to the Material Plane as part of any move action, and then shift back again as a free action. The ability is otherwise identical to the <i>psionic ethereal jaunt</i> power.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (679,'Udoroot','Udoroot',NULL,'Huge','Plant','Psionic','6d8+18 (45 hp)','+0','0 ft.','11 (-2 size, -5 Dex, +8 natural), touch 3, flat-footed 11','+4','-','-','-','15 ft.','0 ft.','Double manifest, psi-like abilities','Blindsight 60 ft., immunity to electricity, plant traits, cold resistance 10, fire resistance 10','Fort +8, Ref +4, Will +5','Str -, Dex -, Con 16, Int 4, Wis 13, Cha 14','Listen +10',NULL,'Iron Will, Lightning Reflexes',NULL,'Temperate forest','Solitary or patch (2-4)','5','1/5 coins; 50% goods; 50% items','Always neutral','7-16 HD (Huge); 17-18 HD (Gargantuan)','-','Blindsight (Ex), Double Manifest (Ex)','Udoroot; CR 5; Huge plant (psionic); HD 6d8+18; hp 45; Init +0; Spd 0 ft.; AC 11 (-2 size, -5 dex, +8 natural), touch 3, flat-footed 11; Base Atk +4; Grp -; Atk -; Full Atk -; Space/Reach 15 ft./0 ft.; SA Double manifest, psi-like abilities; SQ Blindsight 60 ft., immunity to electricity, plant traits, cold resistance 10, fire resistance 10; AL N; SV Fort +8, Ref +4, Will +5; Str -, Dex -, Con 16, Int 4, Wis 13, Cha 14\n\nSkills and Feats: Listen +10; Iron Will, Lightning Reflexes','\n      <div topic=\"Udoroot\" level=\"2\"><p><h2>Udoroot</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Udoroot</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Huge Plant (Psionic)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>6d8+18 (45 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>11 (-2 size, -5 Dex, +8 natural), touch 3, flat-footed 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+4/-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Double manifest, psi-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Blindsight 60 ft., immunity to electricity, plant traits, cold resistance 10, fire resistance 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +8, Ref +4, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str -, Dex -, Con 16, Int 4, Wis 13, Cha 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Iron Will, Lightning Reflexes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate forest<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or patch (2-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>1/5 coins; 50% goods; 50% items<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>7-16 HD (Huge); 17-18 HD (Gargantuan)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>An udoroot can be killed only if its root is dug up or exposed, then burned, hacked apart, or otherwise destroyed. Severing or destroying all six crowns puts the plant out of commission, allowing excavation of the helpless root. The crowns are Medium objects with a hardness of 5 and 7 hit points. To sever a crown, an opponent must use the sunder action. The crowns can also be affected by spells or effects that affect an area or targeted by spells that affect an individual target.</p><p>An udoroot takes no damage from having a crown severed or destroyed. A severed crown dies and can no longer be used to attack, but the udoroot takes no other penalties.  As long as the root system remains intact, the crown regrows in about a month.</p><div topic=\"Double Manifest\" level=\"8\"><p><b>Double Manifest (Ex):</b> An udoroot senses its surroundings and manifests its psi-like abilities through its crowns. It can manifest two psi-like abilities per round, as long as it has at least two crowns remaining.</p>\n</div><div topic=\"Psi-Like Abilities\" level=\"8\"><p><b>Psi-Like Abilities:</b> At will-<i>energy stun</i> (electricity, 2d6, DC 15*), <i>false sensory input</i> (DC 15), <i>id insinuation</i> (two targets, DC 15*), <i>mind thrust</i> (ML 4th, 4d10, DC 14*), <i>telekinetic force</i> (275 lb., DC 15*), <i>thought shield</i> (power resistance 16*); 3/day-<i>astral construct</i> (3rd level*), <i>body adjustment</i>,  <i>mental barrier</i>. </p><p>Manifester level 6th. The save DCs are Charisma-based.</p><p>An udoroot can use its <i>body adjustment</i> power to repair damage to one of its crowns, as long as the crown has not been severed or destroyed.</p><p>*Includes augmentation for the udoroot\'s manifester level.</p>\n</div><div topic=\"Blindsight\" level=\"8\"><p><b>Blindsight (Ex):</b> An udoroot can ascertain all foes by nonvisual means within 60 feet. If its crowns are destroyed, it can no longer perceive its surroundings.</p>\n</div><div topic=\"Plant Traits\" level=\"8\"><p><b>Plant Traits:</b> An udoroot is immune to poison, <i>sleep</i>, paralysis, stunning, polymorphing, and mind-affecting effects (charms, compulsions, phantasms, patterns, and morale effects). It is not subject to critical hits.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (680,'Unbodied','Unbodied',NULL,'Medium','Monstrous Humanoid','Incorporeal, Psionic','4d8+4 (22 hp)','+1','Fly 30 ft. (good) (6 squares)','13 (+1 Dex, +2 deflection), touch 13, flat-footed 12','+4','-','Incorporeal touch +5 melee (1d6)','Incorporeal touch +5 melee (1d6)','5 ft.','5 ft.','Psionic powers, telekinetic force','Assume likeness, incorporeal traits, telepathy 100 ft.','Fort +2, Ref +5, Will +6','Str -, Dex 13, Con 12, Int 15, Wis 14, Cha 15','Bluff +10*, Diplomacy +6, Disguise +10*, Intimidate +6, Listen +6, Sense Motive +6, Spot +6',NULL,'Overchannel, Wild Talent',NULL,'Any','Solitary or illumination (3-6)','5','Half standard','Any','By character class','+4','Assume Likeness (Su), Hide Mind (Su), Telekinetic Force (Su)','Unbodied; CR 5; Medium monstrous humanoid (incorporeal, psionic); HD 4d8+4; hp 22; Init +1; Spd Fly 30 ft. (good) (6 squares); AC 13 (+1 dex, +2 deflection), touch 13, flat-footed 12; Base Atk +4; Grp -; Atk +5 melee (1d6, incorporeal touch); Full Atk +5 melee (1d6, incorporeal touch); Space/Reach 5 ft./5 ft.; SA Psionic powers, telekinetic force; SQ Assume likeness, incorporeal traits, telepathy 100 ft.; AL N; SV Fort +2, Ref +5, Will +6; Str -, Dex 13, Con 12, Int 15, Wis 14, Cha 15\n\nSkills and Feats: Bluff +10*, Diplomacy +6, Disguise +10*, Intimidate +6, Listen +6, Sense Motive +6, Spot +6; Overchannel, Wild Talent','\n      <div topic=\"Unbodied\" level=\"2\"><p><h2>Unbodied</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Unbodied</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Monstrous Humanoid (Incorporeal, Psionic)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>4d8+4 (22 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>Fly 30 ft. (good) (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>13 (+1 Dex, +2 deflection), touch 13, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+4/-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Incorporeal touch +5 melee (1d6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Incorporeal touch +5 melee (1d6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Psionic powers, telekinetic force<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Assume likeness, incorporeal traits, telepathy 100 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +2, Ref +5, Will +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str -, Dex 13, Con 12, Int 15, Wis 14, Cha 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Bluff +10*, Diplomacy +6, Disguise +10*, Intimidate +6, Listen +6, Sense Motive +6, Spot +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Overchannel, Wild Talent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or illumination (3-6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Half standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+4<br/></td>\n\n</tr>\n</table><p>An unbodied uses telepathy to communicate with others.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Psionic Powers\" level=\"8\"><p><b>Psionic Powers:</b> An unbodied manifests powers as a 4th-level psion (telepath). The save DCs are Intelligence-based.</p><p><i>Typical Psion Powers Known</i> (power points 21, base save DC 12 + power level): 1st- <i>detect psionics</i>,  <i>empty mind</i>,  <i>mind thrust</i> (DC 13*), <i>psionic charm</i> (DC 13*); 2nd-<i>brain lock</i> (DC 14), <i>cloud mind</i> (DC 14), <i>energy push</i> (DC 14), <i>read thoughts</i> (DC 14).</p><p>*Power can be augmented.</p>\n</div><div topic=\"Telekinetic Force\" level=\"8\"><p><b>Telekinetic Force (Su):</b> An unbodied can use <i>telekinetic force</i> (DC 15) as a standard action that does not provoke attacks of opportunity. Manifester level 4th. The save DC is Charisma-based.</p>\n</div><div topic=\"Assume Likeness\" level=\"8\"><p><b>Assume Likeness (Su):</b> An unbodied can assume the likeness of any Small, Medium, or Large creature as a standard action that does not provoke attacks of opportunity. Its abilities do not change, but it appears to be that creature, relying on its Bluff and Disguise skills to deflect suspicion.</p>\n</div><div topic=\"Hide Mind\" level=\"8\"><p><b>Hide Mind (Su):</b> An unbodied cannot be identified as psionic by divination spells or clairsentience powers.</p>\n</div><div topic=\"Incorporeal Traits\" level=\"8\"><p><b>Incorporeal Traits:</b> An unbodied is harmed only by other incorporeal creatures, magic weapons, powers, spells, spell-like abilities, and supernatural abilities. It has a 50% chance to ignore any damage from a corporeal source, except for force effects or attacks made with ghost touch weapons. It can pass through solid objects, but not force effects, at will. Its attacks ignore natural armor, armor, and shields, but deflection bonuses and force effects work normally against them. An incorporeal creature always moves silently and cannot be heard with Listen checks if it doesn\'t wish to be.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> An unbodied has a +4 racial bonus on Bluff and Disguise checks. *When using its assume likeness ability, an unbodied gets an additional +10 circumstance bonus on Disguise checks. If it can read an opponent\'s mind, it gets a further +4 circumstance bonus on Bluff and Disguise checks.</p>\n</div>\n</div><div topic=\"Unbodied as Characters\" level=\"3\"><p><h3>Unbodied as Characters</h3></p><p>Unbodied characters possess the following racial traits.</p><ul>\n <li>+2 Dexterity, +2 Constitution, +4 Intelligence, +4 Wisdom, +4 Charisma. As an incorporeal creature, an unbodied has no Strength score.</li>\n <li>Medium size.</li>\n <li>An unbodied has a fly speed of 30 feet (good maneuverability).</li>\n <li>Darkvision out to 60 feet.</li>\n <li>Deflection bonus to Armor Class equal to character\'s Charisma modifier (minimum +1).</li>\n <li>Natural Attack: An unbodied can make a melee touch attack to deal 1d6 points of damage.</li>\n <li>Special Attacks (see above): Psionic powers, telekinetic force. An unbodied who takes levels in psion (telepath) adds its racial manifesting ability and psion levels together to determine its power point reserve, manifester level, and powers known.</li>\n <li>Special Qualities (see above): Assume likeness, incorporeal traits.</li>\n <li>Racial Hit Dice: An unbodied begins with four levels of monstrous humanoid, which provide 4d8 Hit Dice, a base attack bonus of +4, and base saving throw bonuses of Fort +1, Ref +4, and Will +4.</li>\n <li>Racial Skills: An unbodied\'s monstrous humanoid levels give it skill points equal to 7 x (2 + Int modifier). Its class skills are Bluff, Diplomacy, Disguise, Intimidate, Listen, Sense Motive, and Spot. Unbodied have a +4 racial bonus on Bluff checks and Disguise checks. When using its assume likeness ability, an unbodied gets an additional +10 circumstance bonus on Disguise checks. If it can read an opponent\'s mind, it gets a further +4 circumstance bonus on Bluff and Disguise checks.</li>\n <li>Racial Feats: An unbodied\'s monstrous humanoid levels give it two feats.</li>\n <li>Favored Class: Psion (telepath).</li>\n <li>Level Adjustment: +4.</li>\n</ul><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
INSERT INTO monster VALUES (681,'Xeph','Xeph, 1st-Level Warrior',NULL,'Medium','Humanoid','Psionic, Xeph','1d8+1 (5 hp)','+1','30 ft. (6 squares)','15 (+1 Dex, +3 studded leather, +1 light shield), touch 11, flat-footed 14','+1','+1','Rapier +2 melee (1d6/18-20) or longbow +2 ranged (1d8/x3)','Rapier +2 melee (1d6/18-20) or longbow +2 ranged (1d8/x3)','5 ft.','5 ft.','-','Burst, darkvision 60 ft.','Fort +3, Ref +1, Will -1','Str 11, Dex 13, Con 12, Int 10, Wis 9, Cha 8','Climb +2, Jump +2',NULL,'Weapon Finesse',NULL,'Warm forest','Team (2-4), squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level), or band (30-100 plus 150% noncombatants plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)','1/2','Standard','Usually neutral','By character class','+0','Burst (Su)','1st-level warrior xeph; CR 1/2; Medium humanoid (psionic, xeph); HD 1d8+1; hp 5; Init +1; Spd 30 ft. (6 squares); AC 15 (+1 dex, +3 studded leather, +1 light shield), touch 11, flat-footed 14; Base Atk +1; Grp +1; Atk +2 melee (1d6/18-20, rapier) or +2 ranged (1d8/x3, longbow); Full Atk +2 melee (1d6/18-20, rapier) or +2 ranged (1d8/x3, longbow); Space/Reach 5 ft./5 ft.; SA -; SQ Burst, darkvision 60 ft.; AL N; SV Fort +3, Ref +1, Will -1; Str 11, Dex 13, Con 12, Int 10, Wis 9, Cha 8\n\nSkills and Feats: Climb +2, Jump +2; Weapon Finesse','\n      <div topic=\"Xeph\" level=\"2\"><p><h2>Xeph</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Xeph, 1st-Level Warrior<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Humanoid (Psionic, Xeph)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d8+1 (5 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (+1 Dex, +3 studded leather, +1 light shield), touch 11, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Rapier +2 melee (1d6/18-20) or longbow +2 ranged (1d8/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Rapier +2 melee (1d6/18-20) or longbow +2 ranged (1d8/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Burst, darkvision 60 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +1, Will -1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 11, Dex 13, Con 12, Int 10, Wis 9, Cha 8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +2, Jump +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Finesse<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm forest<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Team (2-4), squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level), or band (30-100 plus 150% noncombatants plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n</table><p>Xephs speak their own language and Common.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Burst\" level=\"8\"><p><b>Burst (Su):</b> Three times per day, a xeph can increase his or her speed by 10 feet, plus 10 feet per four character levels beyond 1st, to a maximum increase of 30 feet at 9th character level and higher. These bursts of speed are considered a competence bonus to the xeph\'s base speed. A burst of speed lasts 3 rounds.</p><p>The xeph warrior presented here had the following ability scores before racial adjustments: Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8.</p>\n</div>\n</div><div topic=\"Xephs as Characters\" level=\"3\"><p><h3>Xephs as Characters</h3></p><p>Xeph characters possess the following racial traits.</p><ul>\n <li>-2 Strength, +2 Dexterity.</li>\n <li>Medium size.</li>\n <li>Xeph base land speed is 30 feet.</li>\n <li>Darkvision out to 60 feet.</li>\n <li>Naturally Psionic: Xephs gain 1 bonus power point at 1st level.</li>\n <li>+1 racial bonus on saving throws against powers, spells, and spell-like effects.</li>\n <li>Special Qualities (see above): Burst.</li>\n <li>Racial Feats: A xeph character gains feats according to his or her character class.</li>\n <li>Automatic Languages: Xeph, Common.</li>\n <li>Favored Class: Soulknife.</li>\n <li>Level Adjustment: +0.</li>\n</ul><p/>\n</div>\n</div>\n    ','SRD 3.5 PsionicMonsters');
